WordHunterWoW_ENDesc_Spell[123078] = "Your Pillar of Frost ability grants 5% additional Strength, and Summon Gargoyle lasts 5 sec longer."
WordHunterWoW_ENDesc_Spell[123079] = "Reduces the cooldown of your Vampiric Blood ability by 20 sec."
WordHunterWoW_ENDesc_Spell[123080] = "Increases the healing received from your Death Strike by 10%."
WordHunterWoW_ENDesc_Spell[123082] = "Your Starfall deals 20% additional damage."
WordHunterWoW_ENDesc_Spell[123083] = "Increases the duration of your Moonfire and Sunfire spells by 2 sec."
WordHunterWoW_ENDesc_Spell[123084] = "Your Shred ability deals 5% additional damage."
WordHunterWoW_ENDesc_Spell[123085] = "Increases the duration of your Rip by 4 sec."
WordHunterWoW_ENDesc_Spell[123087] = "Increases the healing received from your Frenzied Regeneration by 10% and increases the dodge granted by your Savage Defense by an additional 5%."
WordHunterWoW_ENDesc_Spell[123088] = "Reduces the mana cost of your Rejuvenation spell by 10%."
WordHunterWoW_ENDesc_Spell[123089] = "Reduces the cooldown of your Swiftmend spell by 3 sec."
WordHunterWoW_ENDesc_Spell[123090] = "Your Kill Command deals 15% additional damage, your Chimera Shot deals 15% additional damage, and your Explosive Shot deals 5% additional damage."
WordHunterWoW_ENDesc_Spell[123091] = "Increases the duration of your Bestial Wrath ability by 6 sec, increases the chance for Black Arrow to trigger Lock and Load by 20%, and increases the damage of Aimed Shot  by 10%."
