WordHunterWoW_ENDesc_Spell[166113] = "Fiona is a loyal companion who never loses her way."
WordHunterWoW_ENDesc_Spell[166116] = "Artificer Romuul's hammer is as mighty as his knowledge of crystalworking."
WordHunterWoW_ENDesc_Spell[166117] = "Artificer Romuul's hammer is as mighty as his knowledge of crystalworking."
WordHunterWoW_ENDesc_Spell[166127] = "Artificer Romuul's hammer is as mighty as his knowledge of crystalworking."
WordHunterWoW_ENDesc_Spell[166141] = "Chieftain Rulkan is the fierce leader of the Shadowmoon Exiles."
WordHunterWoW_ENDesc_Spell[166167] = "Quiet and intense, the alchemist Ang'kra uses her craft to sustain and support her allies."
