WordHunterWoW_ENDesc_Spell[167105] = "Smash the ground and shatter the armor of all enemies within 10 yds, dealing 109 Physical damage and increasing damage you deal to them by 30% for 10 sec. Deals reduced damage beyond 8 targets."
WordHunterWoW_ENDesc_Spell[167192] = "Death Strike reduces the cooldown of Vampiric Blood by 1 sec."
WordHunterWoW_ENDesc_Spell[167218] = "Hardened by the gladiator pits of Stonemaul, Bruto is a master of hand to hand combat."
WordHunterWoW_ENDesc_Spell[167225] = "Hardened by the gladiator pits of Stonemaul, Pitfighter Vaandaam is a master of hand to hand combat."
WordHunterWoW_ENDesc_Spell[167517] = "Unlocks all class abilities not previously unlocked.  You're ready for the full experience.  Good Luck!"
WordHunterWoW_ENDesc_Spell[167518] = "Unlocks all class abilities not previously unlocked.  You're ready for the full experience.  Good Luck!"
WordHunterWoW_ENDesc_Spell[167643] = "The great ogre thief Dagg is a master of subterfuge and disguises."
WordHunterWoW_ENDesc_Spell[167684] = "When Prayer of Mending heals a target, you have a 20% chance to reduce the cooldown of Holy Word: Sanctify by 3 sec."
WordHunterWoW_ENDesc_Spell[167694] = "When you activate Rapture, the mana cost of Power Word: Shield is reduced by 35% for 6 sec."
WordHunterWoW_ENDesc_Spell[167697] = "When you cast Flash of Light, you have a 20% chance to be able to cast a free Light of Dawn."
WordHunterWoW_ENDesc_Spell[167702] = "When you gain Tidal Waves, you have a 8% chance to reduce the mana cost of Chain Heal by 20% for 8 sec."
WordHunterWoW_ENDesc_Spell[167714] = "When you cast 2 sequential Healing Touch spells, the mana cost of your next Wild Growth is reduced by 25%."
WordHunterWoW_ENDesc_Spell[167718] = "Effuse critical strikes reduce the mana cost of your next Renewing Mist by 50%."
WordHunterWoW_ENDesc_Spell[167740] = "When you block a physical attack, you have a chance to increase your shield block value by 20% for 8 sec.\n(Approximately 1.55 procs per minute)"
WordHunterWoW_ENDesc_Spell[167843] = "Tormmok is a centurion of the Gorian Empire. He is a mighty soldier and veteran of countless battles."
WordHunterWoW_ENDesc_Spell[167911] = "Allows you to find and harvest small timber from various types of trees across Draenor."
WordHunterWoW_ENDesc_Spell[167946] = "Allows you to harvest medium sized timber across Draenor."
WordHunterWoW_ENDesc_Spell[167947] = "Allows you to harvest large sized timber across Draenor."
WordHunterWoW_ENDesc_Spell[168109] = "Unlocks access to spending your second tier talent point."
WordHunterWoW_ENDesc_Spell[168110] = "Unlocks access to spending your third tier talent point."
WordHunterWoW_ENDesc_Spell[168111] = "Unlocks access to spending your fourth tier talent point."
WordHunterWoW_ENDesc_Spell[168113] = "Unlocks access to spending your fifth tier talent point."
WordHunterWoW_ENDesc_Spell[168114] = "Unlocks access to spending your sixth tier talent point."
WordHunterWoW_ENDesc_Spell[168534] = "All Elemental damage increased by 14.0%.\n\nYour Lightning Bolt, Lava Burst, and Chain Lightning casts have a 38.4% chance to trigger a second cast on the same target, dealing 25% of normal damage and generating less Maelstrom."
WordHunterWoW_ENDesc_Spell[168816] = "Kimzee can be brash and outspoken but is fiercely loyal to her friends and family."
WordHunterWoW_ENDesc_Spell[169340] = "Instantly kills any creature under level 50, or player under 20% health."
WordHunterWoW_ENDesc_Spell[169661] = "Phylarch the Evergreen, Lord of the Everbloom."
WordHunterWoW_ENDesc_Spell[169987] = "Admiral Taylor is one of the premier commanders of the Alliance military. Few are as decorated or experienced on the battlefield. Even in death, he fights to protect the innocent from  harm."
WordHunterWoW_ENDesc_Spell[170374] = "Your damaging spells incite the earth around you to come to your aid for 6 sec, repeatedly dealing 163 Nature damage to your most recently attacked target."
WordHunterWoW_ENDesc_Spell[170506] = "Unlocks access to the Pet Menagerie.\n\nLevel 1\nAttracts elite pets you can battle for rewards.  Also lets 5 of your battle pets hang out in your garrison.\n\nLevel 2\nIncreases your trap chance and reduces the cooldown of Revive Battle Pets while in Draenor.  Up to 10 of your pets can now hang out in your garrison.\n\nLevel 3\nUnlocks a pet battle daily with unique pet rewards."
WordHunterWoW_ENDesc_Spell[170550] = "Alexi Barov, true heir to the House of Barov."
WordHunterWoW_ENDesc_Spell[170551] = "Weldon Barov, true heir to the House of Barov."
WordHunterWoW_ENDesc_Spell[170799] = "Enveloping Mist reduces the target's chance to be hit with a critical strike by 20% for 6 sec."
WordHunterWoW_ENDesc_Spell[170848] = "Interrupting a spell with Skull Bash resets the cooldown of Tiger's Fury."
WordHunterWoW_ENDesc_Spell[170853] = "Your Ironbark now also grants the target Nature's Grasp, which roots the first 2 attackers for 6 sec."
WordHunterWoW_ENDesc_Spell[170860] = "Increase the duration of Aura Mastery by 2 sec."
WordHunterWoW_ENDesc_Spell[170877] = "Feint also increases your Versatility by 55 for 5 sec."
WordHunterWoW_ENDesc_Spell[170883] = "When you use Vanish, you gain 5 Combo Points and the critical strike chance of your next Mutilate or Envenom is increased by 10%."
WordHunterWoW_ENDesc_Spell[170884] = "Aimed Shot reduces the cooldown of True Shot by 5 sec."
WordHunterWoW_ENDesc_Spell[171109] = "Reduces the cooldown of Hex by 15 sec."
WordHunterWoW_ENDesc_Spell[171121] = "Windfury now deals damage 2 extra times."
WordHunterWoW_ENDesc_Spell[171124] = "Penance now increases the movement speed of a friendly target you heal by 30%, and decreases the movement speed of an enemy target you damage by 50%."
WordHunterWoW_ENDesc_Spell[171141] = "Reduces the cooldown of Pain Suppression by 60 sec."
WordHunterWoW_ENDesc_Spell[171142] = "Reduces the cooldown of Guardian Spirit by 60 sec."
WordHunterWoW_ENDesc_Spell[171146] = "When Dispersion ends, you gain 119 Versatility for 10 sec."
WordHunterWoW_ENDesc_Spell[171151] = "When you use Silence, you gain 30 Insanity."
WordHunterWoW_ENDesc_Spell[171158] = "When Prayer of Mending heals a target, you and the target gain 7 Versatility for 10 sec. Stacks up to 5 times."
WordHunterWoW_ENDesc_Spell[171169] = "When you consume Hot Streak, your Pyroblast target has a 15% increased chance to be critically hit by your Fireball spell for 10 sec."
WordHunterWoW_ENDesc_Spell[171192] = "Soulbinder Tuulani lost her family at a young age. Exarch Maladaar took the bright and eager draenei under his wing and raised her as his own."
WordHunterWoW_ENDesc_Spell[171202] = "Aeda Brightdawn maintains that not all warlocks are \"evil\". They call upon demons and shadow magic, sure, but why does that mean they can't use their powers for good... right?"
WordHunterWoW_ENDesc_Spell[171221] = "Illona always dreamt of one day joining the ancient Auchenai order. When Exarch Maladaar sent out a call for help to any willing and able draenei, Illona took up her grandfather's armor and set off to her destiny."
WordHunterWoW_ENDesc_Spell[171244] = "Ahm was captured by Blademaster Bralok when the cruel orc attacked his home town. The orc had Ahm starved and beaten, but Ahm refused to relent. In death, he continues to persevere and seek revenge against the Iron Horde for their travesties."
WordHunterWoW_ENDesc_Spell[171349] = "Successfully Spellstealing a buff generates a use of Arcane Missiles."
WordHunterWoW_ENDesc_Spell[171351] = "While Arcane Power is active, you can cast Arcane Blast and Arcane Missiles while moving."
WordHunterWoW_ENDesc_Spell[171377] = "Getting stunned, silenced, interrupted, or feared generates 1 Soul Shard. Can only occur once every 15 sec."
WordHunterWoW_ENDesc_Spell[171379] = "After using Demonic Circle: Teleport, you gain 79 Versatility for 10 sec."
WordHunterWoW_ENDesc_Spell[171381] = "When you dispel a harmful Magic or Curse effect from an ally, they gain 59 Versatility for 10 sec."
WordHunterWoW_ENDesc_Spell[171383] = "Getting stunned, silenced, interrupted, or feared generates 1 Soul Shard. Can only occur once every 15 sec."
WordHunterWoW_ENDesc_Spell[171393] = "When you or your pet are below 20% of maximum health, you gain 79 Versatility."
WordHunterWoW_ENDesc_Spell[171408] = "If you hit a player with Mangle while they are casting or channeling a spell, their damage and healing will be reduced by 35% for 3 sec."
WordHunterWoW_ENDesc_Spell[171427] = "Reduces damage taken while Ardent Defender is active by an additional 10%, and when you activate Ardent Defender, it will also apply to the nearest ally within 15 yards."
WordHunterWoW_ENDesc_Spell[171445] = "Increases the damage done by your Breath of Fire by 30%."
WordHunterWoW_ENDesc_Spell[171456] = "Anti-Magic Shell also applies to the nearest ally."
WordHunterWoW_ENDesc_Spell[171478] = "You and your pet share diminishing returns from crowd control effects."
WordHunterWoW_ENDesc_Spell[171489] = "While Survival Instincts is active, 35% of the direct damage you deal will heal the 2 nearest allies."
WordHunterWoW_ENDesc_Spell[171742] = "Nat Pagle is Azeroth's greatest fisherman. He also enjoy's the occasional drink now and then."
WordHunterWoW_ENDesc_Spell[171975] = "Damage done by you or your demon has a chance to grant the other one 5% increased damage for 15 sec."
WordHunterWoW_ENDesc_Spell[172335] = "MEATBALL HUNGRY!!"
WordHunterWoW_ENDesc_Spell[172392] = "A Death Knight from Arthas's legions who has escaped Northrend to pursue his love of fishing."
WordHunterWoW_ENDesc_Spell[172735] = "A goblin lumberjack? Seems reasonable. Not that Penny is reasonable."
WordHunterWoW_ENDesc_Spell[172808] = "There's little you can't solve with a little ingenuity. It also helps to carry an axe, a crossbow, and an attitude."
WordHunterWoW_ENDesc_Spell[172894] = "Betrayed by the Laughing Skull spirits. Well, Xuk them anyway."
WordHunterWoW_ENDesc_Spell[172916] = "Resourceful, confident, and skilled even by Rangari standards."
WordHunterWoW_ENDesc_Spell[173193] = "Benjamin Gibb was once a simple farmer in Lordaeron, taken by the undead plague. The Lich King saw a fearsome warrior within and raised him into a mighty death knight. Since the Lich King's fall, Benjamin serves the Horde vanguard, hoping to etch out a meaning for his cursed existence."
WordHunterWoW_ENDesc_Spell[173838] = "Teaches the blueprints needed to build level one versions of all small, medium and large buildings, excluding the salvage yard."
WordHunterWoW_ENDesc_Spell[173841] = "Renewing Mist now has 3 charges and reduces the remaining cooldown of Rising Sun Kick by 1.0 sec.\n\nRising Sun Kick now reduces the remaining cooldown of Renewing Mist by 1.0 sec."
WordHunterWoW_ENDesc_Spell[174007] = "+0 Versatility"
WordHunterWoW_ENDesc_Spell[174189] = "Tormmok will learn the ability Avatar.\n\n Avatar\nTransform into a colossus for 30 sec, dealing 50% increased damage and removing all roots and snares."
WordHunterWoW_ENDesc_Spell[174441] = "Brands the target, allowing them direct access to Blackhand's Crucible in the Blackrock Foundry on Normal difficulty."
WordHunterWoW_ENDesc_Spell[174443] = "Brands the target, allowing them direct access to Blackhand's Crucible in the Blackrock Foundry on Normal or Heroic difficulty."
WordHunterWoW_ENDesc_Spell[174444] = "Brands the target, allowing them direct access to Blackhand's Crucible in the Blackrock Foundry on Normal, Heroic, or Mythic difficulty."
WordHunterWoW_ENDesc_Spell[174537] = "Illona will learn the ability Guardian of Ancient Kings.\n\n Guardian of Ancient Kings\nSummons a Guardian of Ancient Kings to protect you for 12 sec.  \n\nThe Guardian of Ancient Kings reduces damage taken by 50%."
WordHunterWoW_ENDesc_Spell[174550] = "Aeda Brightdawn will learn the ability Summon Infernal.\n\n Summon Infernal\nSummons a Infernal from the Twisting Nether, impacting for 223 Fire damage and stunning all enemy targets in the area for 2 sec.  The Infernal will serve under your command for 30 sec."
WordHunterWoW_ENDesc_Spell[174553] = "Delvar Ironfist will learn the ability Breath of Sindragosa.\n\n Breath of Sindragosa\nDeals Shadowfrost damage every 1 sec to enemies in a cone in front of you within 12 yards over 6 sec."
WordHunterWoW_ENDesc_Spell[174557] = "Vivianne will learn the ability Meteor.\n\n Meteor\nCalls down a meteor which lands at the target location after 3 sec, dealing Fire damage. Also burns the ground, dealing additional Fire damage every 5.2 sec for 8 sec to enemies in the area."
WordHunterWoW_ENDesc_Spell[174560] = "Talonpriest Ishaal will learn the ability Last Rites.\n\n Last Rites\nMarks the target for death, stunning them and causing them to take 20% increased damage for 9 sec.\n\nWhen Last Rites completes or the target dies, they explode for 0 Shadow damage to nearby enemies within 30 yards."
WordHunterWoW_ENDesc_Spell[174562] = "Leorajh will learn the ability Primal Bloodlust.\n\n Primal Bloodlust\nIncreases haste by 15% for you and your target. Lasts 40 sec."
WordHunterWoW_ENDesc_Spell[174618] = "Thisalee Crow is a Druid of the Talon who commands the skies."
WordHunterWoW_ENDesc_Spell[174619] = "Choluna's experience and wisdom will be invaluable to face the challenges ahead."
WordHunterWoW_ENDesc_Spell[174886] = "Tormmok will gain Master of Arms, allowing him to repair your armor and weapons in the field."
WordHunterWoW_ENDesc_Spell[174887] = "Illona will gain Guiding Light, allowing her to summon a party or raid member to your location in the field."
WordHunterWoW_ENDesc_Spell[174889] = "Aeda will gain Ritual of Summoning, allowing her to summon a party or raid member to your location in the field."
WordHunterWoW_ENDesc_Spell[174904] = "Delvar will gain Death Gate, allowing him to create a portal to your garrison."
WordHunterWoW_ENDesc_Spell[174909] = "Vivianne will gain Portal: Garrison, allowing her to create a portal to your garrison."
WordHunterWoW_ENDesc_Spell[174927] = "Ishaal will gain Courier Raven, allowing him to grant you access to your mail in the field."
WordHunterWoW_ENDesc_Spell[174965] = "Leorajh will gain Windspeaker, allowing him to grant you access to garrison missions in the field."
WordHunterWoW_ENDesc_Spell[174975] = "Having completed the ancient rites, Talonpriest Ishaal now pledges his dark arts in service of the Avatar of Terokk."
WordHunterWoW_ENDesc_Spell[174991] = "The Talon Guards of Skettis are elite warriors trained in a manner now forbidden in Skyreach."
WordHunterWoW_ENDesc_Spell[175015] = "Delvar Ironfist is a surly dwarf that loves battle almost as much as mead."
WordHunterWoW_ENDesc_Spell[175017] = "An exiled saberon shaman, Leorajh expanded his mind with an Apexis relic and seeks new allies in need of his powerful healing arts."
WordHunterWoW_ENDesc_Spell[175686] = "Placeholder for level 75 talented active ability."
WordHunterWoW_ENDesc_Spell[176075] = "Velonara was one of Sylvanas' low-ranking rangers, but her success in the Scarlet Monastery during the Cataclysm opened up new opportunities for her. When the Dark Lady asked for volunteers to make the trek into Draenor, Velonara answered without hesitation. Any opportunity to please the Dark Lady is worth the risk."
WordHunterWoW_ENDesc_Spell[176101] = "Hulda Shadowblade dreaded her early life as a Dark Iron, living in what she considered cowardly conditions within the depths of Blackrock Mountain. The day Moira took one of the seats of power on the Council of Three Hammers, Hulda called Ironforge her new home, vowing to fulfill any desire her  Queen-Regent had with her blades."
WordHunterWoW_ENDesc_Spell[176242] = "Teleports you to Warspear."
WordHunterWoW_ENDesc_Spell[176244] = "Creates a portal, teleporting group members that use it to Warspear."
WordHunterWoW_ENDesc_Spell[176246] = "Creates a portal, teleporting group members that use it to Stormshield."
WordHunterWoW_ENDesc_Spell[176248] = "Teleports you to Stormshield."
WordHunterWoW_ENDesc_Spell[176571] = "A wily gnome of questionable morals, Millhouse is ready to light someone up at the slightest provocation."
WordHunterWoW_ENDesc_Spell[177399] = "Summon or dismiss Ikky as a companion."
WordHunterWoW_ENDesc_Spell[178819] = "When you kill an enemy that yields experience or honor, your next Death Strike within 20 sec is free and heals for an additional 10% of maximum health."
WordHunterWoW_ENDesc_Spell[178940] = "Killing an enemy sometimes creates a Soul Fragment that is consumed when you approach it, healing you for 20% of maximum health.\n\nIf the Soul Fragment came from a Demon, you will deal 20% increased damage for 15 sec."
WordHunterWoW_ENDesc_Spell[178976] = "Increases your Agility by 5% while wearing only leather armor."
WordHunterWoW_ENDesc_Spell[179057] = "Unleash an eruption of fel energy, dealing 9 Chaos damage and stunning all nearby enemies for 3 sec."
WordHunterWoW_ENDesc_Spell[179107] = "Your damaging spell casts have a 10% chance to cause an Arcane eruption under your target."
WordHunterWoW_ENDesc_Spell[179108] = "Intellect increased by 11."
WordHunterWoW_ENDesc_Spell[179110] = "Versatility increased by 14."
WordHunterWoW_ENDesc_Spell[179111] = "Casting a healing spell has a 5% chance to cast Wave of Light."
WordHunterWoW_ENDesc_Spell[179114] = "Agility increased by 11."
WordHunterWoW_ENDesc_Spell[179115] = "Your special attacks have a chance to increase your Energy regeneration rate by 30% for 6 sec.  (Approximately 1.00 procs per minute)"
