WordHunterWoW_ENDesc_Spell[376027] = "Unlocks the ability to ride skyriding mounts, using momentum and paired abilities to traverse the skies."
WordHunterWoW_ENDesc_Spell[376079] = "Throw a spear at the target location, chaining all enemies in the area to the spear's location and dealing 85 Physical damage instantly and an additional 128 Physical damage over 6 sec. \n\nWhile the spear is active, activating this ability will cause you to leap to the spear, dealing 16 Physical damage to all targets.\n\nAll damage dealt reduced beyond 5 targets.\n\nGenerates 10 Rage."
WordHunterWoW_ENDesc_Spell[376103] = "Conjure a radiant spark that causes 442 Arcane damage instantly, and an additional 322 damage over 12 sec.\n\nThe target takes 10% increased damage from your direct damage spells, stacking each time they are struck. This effect ends after 4 spells."
WordHunterWoW_ENDesc_Spell[376138] = "Empower spells increase your Essence regeneration rate by 100% for 8 sec."
WordHunterWoW_ENDesc_Spell[376150] = "Dream Breath's cooldown is reduced by 6 sec."
WordHunterWoW_ENDesc_Spell[376164] = "Your Magic damage done is increased by 2%."
WordHunterWoW_ENDesc_Spell[376166] = "Your Stamina is increased by 6%."
WordHunterWoW_ENDesc_Spell[376179] = "Red spells deal 20% additional damage and healing."
WordHunterWoW_ENDesc_Spell[376204] = "Time Dilation gains an additional charge, and its cooldown is reduced by 10 sec."
WordHunterWoW_ENDesc_Spell[376207] = "15% of delayed damage from Time Dilation is absorbed."
WordHunterWoW_ENDesc_Spell[376236] = "Temporal Anomaly applies Echo at 30% effectiveness."
WordHunterWoW_ENDesc_Spell[376237] = "Temporal Anomaly reduces the cooldowns of your empower spells by 5 sec."
WordHunterWoW_ENDesc_Spell[376239] = "Your healing is increased by 10% on targets with your Reversion."
WordHunterWoW_ENDesc_Spell[376240] = "Reversion, Time Dilation, Echo, and Temporal Anomaly last 15% longer and cost 15% less mana."
WordHunterWoW_ENDesc_Spell[376251] = "Increases your maximum Runic Power by 5.\n\nIncreases Rune regeneration rate by 10%."
WordHunterWoW_ENDesc_Spell[376281] = "Damaging a powerful foe during the grand hunt grants 30% Critical Strike for 30 sec.\n\nThis effect may only occur once every 1.5 min"
WordHunterWoW_ENDesc_Spell[376282] = "Slaying a creature in the grand hunt grants 1% increased Intellect for 30 sec. This effect stacks up to 20 times."
WordHunterWoW_ENDesc_Spell[376359] = "Spiral forward a great distance, increasing speed.\n\nWhirling Surge dismounts airborne enemy players."
WordHunterWoW_ENDesc_Spell[376556] = "This mystical cloth can only be woven at a special loom in the Azure Archives, located in the southern area of The Azure Span."
WordHunterWoW_ENDesc_Spell[376557] = "This cloth can only be woven at a special loom found at the Temporal Conflux, located in the south of Thaldraszus."
WordHunterWoW_ENDesc_Spell[376611] = "Refines 5 Quality  leather gathered from the creatures of the Dragon Isles to 1 Quality ."
WordHunterWoW_ENDesc_Spell[376612] = "Refines 5 Quality  leather gathered from the creatures of the Dragon Isles to 1 Quality ."
WordHunterWoW_ENDesc_Spell[376613] = "Refines 5 Quality  scales gathered from the creatures of the Dragon Isles to 1 Quality ."
WordHunterWoW_ENDesc_Spell[376614] = "Refines 5 Quality  scales gathered from the creatures of the Dragon Isles to 1 Quality ."
WordHunterWoW_ENDesc_Spell[376743] = "Flap forward a short distance, gaining speed.\nMax 2 Charges"
WordHunterWoW_ENDesc_Spell[376744] = "Flap upward, gaining height at the cost of some momentum.\nMax 1 Charge"
WordHunterWoW_ENDesc_Spell[376777] = "While falling from a high location, your mount extends its wings to propel you both forward.\n\nPointing yourself downward grants more momentum. Evening out can transfer that momentum forward.\n\nPointing yourself upward slows you down. When at your slowest, you will start to fall slowly toward the ground.\n\nYou also gain access to the following abilities:\n\nSurge Forward\nFlap forward.\n\nSurge Forward evades obstacles encountered in time trials and races.\n\nSkyward Ascent\nFlap upward."
WordHunterWoW_ENDesc_Spell[376872] = "Your Living Flame has a 20% chance to cause an Essence Burst, making your next Disintegrate or Pyre cost no Essence."
WordHunterWoW_ENDesc_Spell[376888] = "During Deep Breath and Dragonrage you gain the maximum benefit of Mastery: Giantkiller regardless of targets' health.\n\nUnbound Flame always gains the maximum benefit."
WordHunterWoW_ENDesc_Spell[376930] = "Your healing done and healing received are increased by 2%."
WordHunterWoW_ENDesc_Spell[376938] = "Rime empowered Howling Blast deals 50% increased damage to secondary targets.\n\nRemorseless Winter deals 6% increased damage to enemies it hits, stacking up to 10 times."
WordHunterWoW_ENDesc_Spell[376996] = "Increases the duration of Divine Steed by 2 sec."
WordHunterWoW_ENDesc_Spell[377043] = "Judgment's damage is increased by 10%."
WordHunterWoW_ENDesc_Spell[377047] = "Frostwyrm's Fury has 50% reduced cooldown and Freezes all enemies hit for 3 sec."
WordHunterWoW_ENDesc_Spell[377053] = "Your Crusader Strike causes enemies struck to deal 10% reduced damage to you for 8 sec."
WordHunterWoW_ENDesc_Spell[377056] = "Remorseless Winter damage is increased by 35%. The first time Remorseless Winter deals damage to 3 different enemies, you gain Rime."
WordHunterWoW_ENDesc_Spell[377065] = "Healing from Vampiric Touch and Shadow Word: Madness when you are at maximum health will shield you for the same amount. The shield cannot exceed 10% of your maximum health."
WordHunterWoW_ENDesc_Spell[377073] = "Runic Empowerment has a 25% chance to refund 1 additional Rune."
WordHunterWoW_ENDesc_Spell[377076] = "Frost Strike and Glacial Advance have a 15% increased chance to trigger Rime and Howling Blast generates 8 Runic Power while Rime is active."
WordHunterWoW_ENDesc_Spell[377082] = "You are able to move while communing with the Dream."
WordHunterWoW_ENDesc_Spell[377086] = "Emerald Communion increases your maximum health by 20% for 15 sec."
WordHunterWoW_ENDesc_Spell[377098] = "Consuming Killing Machine grants 1% critical strike chance for 10 sec, stacking up to 5 times. At 5 stacks your next Killing Machine consumes the stacks and grants you 10% increased Frost damage for 10 sec."
WordHunterWoW_ENDesc_Spell[377099] = "Consuming a full Temporal Compression grants you Essence Burst."
WordHunterWoW_ENDesc_Spell[377100] = "Each time you gain Essence Burst, your critical heals are 230% effective instead of the usual 200% for 10 sec."
WordHunterWoW_ENDesc_Spell[377128] = "Consecration heals you and 5 allies within it for 2 every 0.9 sec."
WordHunterWoW_ENDesc_Spell[377190] = "When Pillar of Frost expires, your Strength is increased by 8% for 6 sec. This effect lasts 2 sec longer, up to 20 sec, for each Obliterate and Frostscythe critical strike during Pillar of Frost."
WordHunterWoW_ENDesc_Spell[377210] = "Thrash and Maul grant you an absorb shield for 35% of the damage dealt for 15 sec."
WordHunterWoW_ENDesc_Spell[377226] = "Pillar of Frost now summons a Remorseless Winter that lasts 4 sec longer.\n\nEach enemy Remorseless Winter damages grants you 5% Mastery, up to 26% for 15 sec."
WordHunterWoW_ENDesc_Spell[377349] = "Mind Flay has a chance to spawn a Void Tendril that channels Mind Flay or Void Lasher that channels Mind Sear at your target.\n\n Mind Flay\nAssaults the target's mind with Shadow energy, causing 1,245 Shadow damage over 10 sec and slowing their movement speed by 30%.\n\nGenerates 5 Insanity over the duration.\n\n Mind Sear\nCorrosive shadow energy radiates from the target, dealing 825 Shadow damage over 10 sec to all enemies within 10 yards of the target. Damage reduced beyond 5 targets.\n\nGenerates 5 Insanity over the duration."
WordHunterWoW_ENDesc_Spell[377351] = "Enemies suffer 12% increased damage from Chill Streak each time they are struck by it."
WordHunterWoW_ENDesc_Spell[377376] = "Chill Streak's bounce range is increased by 2 yds and each time Chill Streak bounces it has a 25% chance to increase the maximum number of bounces by 1."
WordHunterWoW_ENDesc_Spell[377422] = "Shadow Word: Pain deals an additional 3% damage. When an enemy dies while afflicted by your Shadow Word: Pain, you gain 0.5% Mana."
WordHunterWoW_ENDesc_Spell[377440] = "Magus of the Dead grants you 1.0% Haste for 15 sec.\n\nMultiple applications may overlap."
WordHunterWoW_ENDesc_Spell[377485] = "Unlocks the ability Winds of the Isles.\n\nYou can now detect and utilize gale winds that redirect your flight and propel you onward, boosting your speed in the direction of the gale."
WordHunterWoW_ENDesc_Spell[377509] = "Summon a flying projection of yourself that heals allies you pass through for 778. Detonating your projection dispels all nearby allies of Magical effects, and heals for 3,698 over 20 sec."
WordHunterWoW_ENDesc_Spell[377514] = "Scourge Strike, Festering Strike, and Death Coil deal 30% additional damage to enemies below 35% health.\n\nDark Transformation resets Soul Reaper's cooldown and allows it to be used on any target."
WordHunterWoW_ENDesc_Spell[377537] = "Death Coil and Epidemic debilitate your enemy applying Death Rot causing them to take 1% increased Shadow damage, up to 10% from you for 10 sec. If Death Coil or Epidemic consume Sudden Doom it applies two stacks of Death Rot."
WordHunterWoW_ENDesc_Spell[377580] = "Putrefy deals 20% increased damage, has 2 additional charges and consumes up to 2 available charges."
WordHunterWoW_ENDesc_Spell[377587] = "Dark Transformation increases the attack speed and damage of you and your Monstrosity by 5% for 15 sec."
WordHunterWoW_ENDesc_Spell[377590] = "Spending Runic Power increases your Strength by 0.50% for 20 sec.\n\nMultiple applications may overlap."
WordHunterWoW_ENDesc_Spell[377592] = "Diseased enemies take 1% increased damage from you per disease they are affected by."
WordHunterWoW_ENDesc_Spell[377629] = "Heart Strike heals you for 0.25% health for each enemy hit while affected by Blood Plague."
WordHunterWoW_ENDesc_Spell[377637] = "Dancing Rune Weapon's cooldown is reduced by 30 sec and now generates 5 Bone Shield charges."
WordHunterWoW_ENDesc_Spell[377668] = "Summons 1 additional copy of Dancing Rune Weapon and increases its duration by 4 sec."
WordHunterWoW_ENDesc_Spell[377709] = "Unlocks the ability Whirling Surge.\n\nSpiral forward a great distance, increasing speed."
WordHunterWoW_ENDesc_Spell[377796] = "Healing you receive is increased by 4%."
WordHunterWoW_ENDesc_Spell[377801] = "For 3 sec after leaving Cat Form or Travel Form, you retain up to 25% movement speed."
WordHunterWoW_ENDesc_Spell[377811] = "Frenzied Regeneration's healing is increased by up to 80% based on your missing health.\n\nFrenzied Regeneration has 1 additional charge."
WordHunterWoW_ENDesc_Spell[377835] = "Stampeding Roar's radius is increased by 30%.\n\nYour movement speed is increased by 5%."
WordHunterWoW_ENDesc_Spell[377842] = "For 4 sec after shifting into Bear Form, your health and armor are increased by 15%."
WordHunterWoW_ENDesc_Spell[377847] = "When you fall below 40% health, you cast Frenzied Regeneration, up to once every 120 sec."
WordHunterWoW_ENDesc_Spell[377920] = "Your Vigor is increased to 4."
WordHunterWoW_ENDesc_Spell[377921] = "Your Vigor is increased to 5."
WordHunterWoW_ENDesc_Spell[377922] = "Your Vigor is increased to 6."
WordHunterWoW_ENDesc_Spell[377933] = "Astral Shift reduces damage taken by an additional 20%."
WordHunterWoW_ENDesc_Spell[377938] = "Your Vigor regeneration rate is accelerated to 1 Vigor every 25 sec while grounded."
WordHunterWoW_ENDesc_Spell[377939] = "Your Vigor regeneration rate is accelerated to 1 Vigor every 20 sec while grounded."
WordHunterWoW_ENDesc_Spell[377940] = "Your Vigor regeneration rate is accelerated to 1 Vigor every 15 sec while grounded."
WordHunterWoW_ENDesc_Spell[377964] = "Thrill of the Skies generates 1 Vigor every 10 sec."
WordHunterWoW_ENDesc_Spell[377967] = "Thrill of the Skies generates 1 Vigor every 5 sec."
WordHunterWoW_ENDesc_Spell[378002] = "Movement speed increased by 4%."
WordHunterWoW_ENDesc_Spell[378004] = "Critical strike chance increased by 2%."
WordHunterWoW_ENDesc_Spell[378007] = "Pet damage increased by 0%."
WordHunterWoW_ENDesc_Spell[378010] = "Kill Command damage increased by 5%."
WordHunterWoW_ENDesc_Spell[378014] = "Serpent Sting's damage applies Latent Poison to the target, stacking up to 10 times. Mongoose Bite consumes all stacks of Latent Poison, dealing 7 Nature damage to the target per stack consumed."
WordHunterWoW_ENDesc_Spell[378075] = "Ghost Wolf removes snares and increases your movement speed by an additional 25% for the first 3 sec. May only occur once every 20 sec."
WordHunterWoW_ENDesc_Spell[378077] = "When you cast Spiritwalker's Grace, you become immune to Silence and Interrupt effects for 5 sec."
WordHunterWoW_ENDesc_Spell[378079] = "Your Hex target is slowed by 70% during Hex and for 6 sec after it ends."
WordHunterWoW_ENDesc_Spell[378081] = "Your next healing or damaging Nature spell is instant cast and costs no mana."
WordHunterWoW_ENDesc_Spell[378094] = "Increases the healing done by Healing Stream Totem by 21%."
WordHunterWoW_ENDesc_Spell[378193] = "Elemental Fury increases critical strike damage by an additional 25%."
WordHunterWoW_ENDesc_Spell[378196] = "Reversion instantly heals the target for 15% of damage taken in the last 5 sec."
WordHunterWoW_ENDesc_Spell[378205] = "Barbed Shot damage increased by 1%."
WordHunterWoW_ENDesc_Spell[378207] = "While Beast Cleave is active, Kill Command now also strikes nearby enemies for 20% of damage dealt. Deals reduced damage beyond 8 targets."
WordHunterWoW_ENDesc_Spell[378209] = "All pet damage dealt increased by 3%."
WordHunterWoW_ENDesc_Spell[378210] = "Kill Shot deals 10% increased damage for each of your active pets. Stacks up to 5 times."
WordHunterWoW_ENDesc_Spell[378211] = "Your Healing Surge is 25% more effective on yourself."
WordHunterWoW_ENDesc_Spell[378241] = "Increases the damage of your Lightning Bolt, Chain Lightning, and Storm Elemental by 15%."
WordHunterWoW_ENDesc_Spell[378244] = "Cobra Shot Focus cost reduced by 5. Cobra Shot damage increased by 10%."
WordHunterWoW_ENDesc_Spell[378255] = "Ascendance summons a Greater Fire Elemental to rain destruction on your enemies for 20 sec. \n\nWhile the Fire Elemental is active, Flame Shock deals damage 33% faster, and newly applied Flame Shocks last 100% longer."
WordHunterWoW_ENDesc_Spell[378266] = "Reduces the cooldown of Flame Shock and Voltaic Blaze by 1.5 sec.\n\nFlame Shock deals damage 15% faster."
WordHunterWoW_ENDesc_Spell[378268] = "When you cast Earth Shock, Elemental Blast, or Earthquake, gain Lava Surge and increase the damage of your next Lava Burst by 10%."
WordHunterWoW_ENDesc_Spell[378270] = "Each stack of Maelstrom Weapon consumed has a 0.6% chance to activate Ascendance for 6.0 sec.\n\n Ascendance\nTransform into an Air Ascendant for 15 sec and unleash Doom Winds, reducing the cooldown and cost of Stormstrike by 60%, and transforming your auto attack and Stormstrike into Wind attacks which bypass armor and have a 30 yd range."
WordHunterWoW_ENDesc_Spell[378271] = "Dealing direct Fire, Frost, and Nature damage within 10 sec will increase all damage dealt by 10% for 10 sec. This can only occur once every 30 sec."
WordHunterWoW_ENDesc_Spell[378279] = "Each enemy hit by Avenger's Shield reduces the remaining cooldown on Guardian of Ancient Kings by 1.0 sec.\n\nWhen you drop below 30% health, you become infused with Guardian of Ancient Kings for 4 sec. This cannot occur again for 45 sec."
WordHunterWoW_ENDesc_Spell[378285] = "Your Avenger's Shield is imbued with holy fire, causing it to deal 4 Holy damage to all enemies within 5 yards of each target hit."
WordHunterWoW_ENDesc_Spell[378310] = "Flame Shock damage over time critical strikes reduce the cooldown of your Fire and Storm Elemental by 1.0 sec, and Flame Shock has a 50% increased critical strike chance."
WordHunterWoW_ENDesc_Spell[378405] = "Word of Glory heals for an additional 40% over 10 sec.\n\nIncreased by 200% if cast on yourself while you are afflicted by a harmful damage over time effect."
WordHunterWoW_ENDesc_Spell[378406] = "Frozen Orb has a 100% chance to grant Brain Freeze."
WordHunterWoW_ENDesc_Spell[378409] = "While skyriding at middle speed and above, you gain stacks of Skyrider's Initiative, up to 10.\n\nWhen landing at mid-to-high speeds, you create a shockwave, damaging enemies for 27 per stack, split among them, and disorienting them for 3 sec. Landing at low speeds cancels Skyrider's Initiative."
WordHunterWoW_ENDesc_Spell[378425] = "Your Lay on Hands, Divine Shield, Blessing of Protection, and Blessing of Spellwarding have 15% reduced cooldown."
WordHunterWoW_ENDesc_Spell[378427] = "Energy cost of Feint and Crimson Vial reduced by 10."
WordHunterWoW_ENDesc_Spell[378436] = "Increases the non-damaging effects of your weapon poisons by 20%."
WordHunterWoW_ENDesc_Spell[378437] = "Hover prevents movement speed from being reduced below 100%."
WordHunterWoW_ENDesc_Spell[378438] = "Fire Breath burns away 2 beneficial Magic effects from all targets."
WordHunterWoW_ENDesc_Spell[378441] = "Freeze an ally's timestream for 5 sec. While frozen in time they are invulnerable, cannot act, and auras do not progress.\n\nYou may reactivate Time Stop to end this effect early."
WordHunterWoW_ENDesc_Spell[378442] = "When your primary pet uses Stomp, apply Barbed Shot to a target hit by that Stomp. This Barbed Shot will not cause an extra Stomp."
WordHunterWoW_ENDesc_Spell[378443] = "Deal 379 Nature damage every 1.8 sec to up to 5 enemies inside of your Healing Rain."
WordHunterWoW_ENDesc_Spell[378444] = "While Obsidian Scales is active you gain immunity to interrupt, silence, and pushback effects."
WordHunterWoW_ENDesc_Spell[378448] = "Ice Lance strikes 1 additional target at 50% effectiveness, preferring enemies with more stacks of Freezing."
WordHunterWoW_ENDesc_Spell[378457] = "Avenger's Shield jumps to 2 additional targets."
WordHunterWoW_ENDesc_Spell[378740] = "Kill Command damage increased by 5%."
WordHunterWoW_ENDesc_Spell[378743] = "Kill Command has a 20% chance to also summon a Dire Beast to attack your target for 8 sec."
WordHunterWoW_ENDesc_Spell[378745] = "Every 5 Dire Beasts summoned resets the cooldown of Kill Command, and reduces the Focus cost and cooldown of Kill Command by 50% for 8 sec."
WordHunterWoW_ENDesc_Spell[378750] = "Cobra Shot has a 25% chance to make your next Kill Command consume no Focus."
WordHunterWoW_ENDesc_Spell[378756] = "Gives your Chill effects a 10% chance to freeze the target for 4 sec."
WordHunterWoW_ENDesc_Spell[378759] = "Whenever you successfully Freezing Trap an enemy, gain 20 Focus and increase all Focus gained by 50% for 5 sec."
WordHunterWoW_ENDesc_Spell[378762] = "Avenger's Shield deals 10% increased damage to its primary target."
WordHunterWoW_ENDesc_Spell[378765] = "Kill Shot critical strike chance and critical strike damage increased by 20%."
WordHunterWoW_ENDesc_Spell[378766] = "Aimed Shot and Rapid Fire critical strike chance increased by 5%."
WordHunterWoW_ENDesc_Spell[378767] = "Consuming Precise Shots reduces the cooldown of Aimed Shot by 1.00 sec."
WordHunterWoW_ENDesc_Spell[378769] = "Aimed Shot now has a 15% chance and Rapid Fire now has a 25% chance to grant Deathblow.\n\nKill Shot critical strike damage is increased by 25%.\n\n Deathblow\nThe cooldown of Kill Shot is reset. Your next Kill Shot can be used on any target, regardless of their current health."
WordHunterWoW_ENDesc_Spell[378771] = "When you fall below 40% health, Bursting Shot and Scatter Shot have their cooldown immediately reset. This can only occur once every 25 sec."
WordHunterWoW_ENDesc_Spell[378773] = "Purges the enemy target, removing 2 beneficial Magic effects."
WordHunterWoW_ENDesc_Spell[378776] = "Your successful Purge, Cleanse Spirit, Healing Stream Totem, Hex, and Wind Shear casts generate 8 Maelstrom during combat."
WordHunterWoW_ENDesc_Spell[378779] = "Thunderstorm knocks enemies up instead of away and its cooldown is reduced by 5 sec."
WordHunterWoW_ENDesc_Spell[378807] = "While Stealth or Shadow Dance is active, you move 20% faster."
WordHunterWoW_ENDesc_Spell[378813] = "Movement speed increased by 15%."
WordHunterWoW_ENDesc_Spell[378845] = "When Avenger's Shield strikes a single enemy, it deals 100% additional Holy damage."
WordHunterWoW_ENDesc_Spell[378848] = "Successfully interrupting an enemy with Mind Freeze grants 10 Runic Power and reduces its cooldown by 3 sec."
WordHunterWoW_ENDesc_Spell[378888] = "Aimed Shot also fires a Serpent Sting at the primary target.\n\n Serpent Sting\nFire a shot that poisons your target, causing them to take 10 Nature damage instantly and an additional 48 Nature damage over 18 sec."
WordHunterWoW_ENDesc_Spell[378905] = "Each Wind Arrow fired reduces the cooldown of Rapid Fire by 0.5 sec, and every 8 Wind Arrows fired increases the duration of your next Trueshot by 1.0 sec, up to a maximum of 10.0 sec."
WordHunterWoW_ENDesc_Spell[378907] = "Critical strike damage increased by 2%."
WordHunterWoW_ENDesc_Spell[378910] = "Trick Shots now ricochets to 2 fewer targets, but each ricochet deals an additional 25% damage."
WordHunterWoW_ENDesc_Spell[378913] = "Trick Shots now causes Aimed Shot and Rapid Fire to ricochet to 2 additional targets.\n\nAspect of the Hydra's damage bonus is increased by 15%."
WordHunterWoW_ENDesc_Spell[378916] = "All damage done by your pet is increased by 10%."
WordHunterWoW_ENDesc_Spell[378919] = "Frostbolt and Flurry critical strike damage increased by 20%."
WordHunterWoW_ENDesc_Spell[378934] = "The damage of your auto-attacks is increased by 25%.\n\nYour Agility is increased by 3%, increased by an additional 1% while dual-wielding."
WordHunterWoW_ENDesc_Spell[378937] = "Wildfire Bomb and Boomstick damage increased by 5%."
WordHunterWoW_ENDesc_Spell[378940] = "When you cast Kill Command, you have a 30% chance to throw a hatchet at your target, dealing 35 Physical damage."
WordHunterWoW_ENDesc_Spell[378947] = "Flurry has a 12% chance each hit to call down an icy comet, crashing into your target and nearby enemies for 632 Frost damage.\n\nApplies 1 stack of Freezing."
WordHunterWoW_ENDesc_Spell[378948] = "Critical damage dealt increased by 2%."
WordHunterWoW_ENDesc_Spell[378950] = "Raptor Strike damage increased by 10%."
WordHunterWoW_ENDesc_Spell[378951] = "Damage of Flanking Strike and Butchery increased by 5% and all damage dealt by Wildfire Bomb increased by 5%."
WordHunterWoW_ENDesc_Spell[378953] = "Mongoose Bite damage increased by 5%."
WordHunterWoW_ENDesc_Spell[378955] = "All damage dealt by your pet is increased by 10%."
WordHunterWoW_ENDesc_Spell[378961] = "You and your pets maximum Focus is increased by 10."
WordHunterWoW_ENDesc_Spell[378962] = "The cooldown of Spearhead is reduced by 30 sec and Spearhead's bleed now increases you and your pet's critical strike damage against the target by 30%."
WordHunterWoW_ENDesc_Spell[378967] = "Surge Forward evades Scalechillers, Scalechargers, and other obstacles encountered in time trials and races."
WordHunterWoW_ENDesc_Spell[378970] = "Whirling Surge evades Wingshredders and dismounts airborne enemy players."
WordHunterWoW_ENDesc_Spell[378986] = "Store 5% of your damage, up to 1,900. Your next Regrowth consumes all stored damage to increase its healing."
WordHunterWoW_ENDesc_Spell[378988] = "You gain 3% of a stat while in each form:\n\nNo Form: Haste\nCat Form: Critical Strike\nBear Form: Versatility\nMoonkin Form: Mastery"
WordHunterWoW_ENDesc_Spell[378996] = "Slice and Dice heals you for up to 1% of your maximum health per 3 sec."
WordHunterWoW_ENDesc_Spell[379005] = "Enemies have 30% reduced damage and healing for 6 sec after Blind or Sap's effect on them ends."
WordHunterWoW_ENDesc_Spell[379008] = "While in your Consecration, your Shield of the Righteous and Word of Glory have 10% increased initial damage and healing."
WordHunterWoW_ENDesc_Spell[379021] = "While in your Consecration and for 4.0 sec after leaving it, your damage taken is reduced by 5%."
WordHunterWoW_ENDesc_Spell[379022] = "Consecration lasts 2 sec longer and its damage is increased by 20%."
WordHunterWoW_ENDesc_Spell[379049] = "Frostbolt and Flurry have a 30% chance to generate 2 Icicles."
WordHunterWoW_ENDesc_Spell[379391] = "Divine Toll's, Holy Armament's, and Holy Prism's cooldown is reduced by 15 sec."
WordHunterWoW_ENDesc_Spell[379993] = "Casting Glacial Spike has a 100% chance to grant you Fingers of Frost."
WordHunterWoW_ENDesc_Spell[380154] = "Your Frost spells deal 20% more damage to targets that are rooted and frozen."
WordHunterWoW_ENDesc_Spell[380188] = "Enemies hit by Avenger's Shield deal 10% reduced melee damage to you for 10 sec."
WordHunterWoW_ENDesc_Spell[381244] = "Casting Ice Lance on Frozen targets has a 100% chance to generate an Icicle."
WordHunterWoW_ENDesc_Spell[381284] = "Unlocks access to cataloging activities within the Dragon Isles."
WordHunterWoW_ENDesc_Spell[381451] = "While Soaring through the air, pointing yourself toward any given direction sends you in that direction.\n\nPointing yourself downward grants more momentum. Evening out can transfer that momentum forward.\n\nPointing yourself upward slows you down. When at your slowest, you will start to fall slowly toward the ground, forward and down.\n\nYou also gain access to the following abilities:\n\n Surge Forward\nFlap forward a short distance, gaining speed.\nMax 2 Charges\n\n Skyward Ascent\nFlap upward, gaining height at the cost of some momentum.\nMax 1 Charge"
WordHunterWoW_ENDesc_Spell[381542] = "Increases the critical strike chance of your attacks that generate combo points by 5%."
WordHunterWoW_ENDesc_Spell[381543] = "Increases the damage of your weapon poisons by 10%."
WordHunterWoW_ENDesc_Spell[381619] = "Versatility increased by 3%."
WordHunterWoW_ENDesc_Spell[381620] = "Ambush generates 1 additional combo point."
WordHunterWoW_ENDesc_Spell[381621] = "Energy cost of finishing moves reduced by 6%."
WordHunterWoW_ENDesc_Spell[381623] = "Restore 100 Energy.\n\nWhen your Energy is reduced below 30, drink a Thistle Tea."
WordHunterWoW_ENDesc_Spell[381624] = "Increases the application chance of your weapon poisons by 5%."
WordHunterWoW_ENDesc_Spell[381626] = "Garrote and Rupture damage increased by 15%."
WordHunterWoW_ENDesc_Spell[381627] = "Kidney Shot and Rupture also apply Internal Bleeding, dealing up to 84 Bleed damage over 6 sec, based on combo points spent."
WordHunterWoW_ENDesc_Spell[381629] = "Fan of Knives has 5% increased critical strike chance and its critical strikes always apply your weapon poisons."
WordHunterWoW_ENDesc_Spell[381630] = "Shadowstep's cooldown is reduced by 33% when used on a target afflicted by your Garrote."
WordHunterWoW_ENDesc_Spell[381631] = "Fan of Knives has its radius increased to 12 yds, deals 20% more damage, and an additional 10% when striking 5 or more targets."
WordHunterWoW_ENDesc_Spell[381632] = "Garrote deals 50% increased damage and has no cooldown when used from Stealth and for 6 sec after breaking Stealth."
WordHunterWoW_ENDesc_Spell[381637] = "Coats your weapons with a Non-Lethal Poison that lasts for 1 hour. Each strike has a 30% chance of poisoning the enemy, reducing their damage by 4.0% for 1 min."
WordHunterWoW_ENDesc_Spell[381640] = "Your weapon poisons and Nature or Bleed damage over time abilities deal 1% increased damage to targets for each of your lethal poison or damage over time effects on them."
WordHunterWoW_ENDesc_Spell[381647] = "Reduces the cooldown of Astral Shift by 30 sec."
