WordHunterWoW_ENDesc_Spell[381674] = "Increases the damage of your Lightning Bolt by 10%."
WordHunterWoW_ENDesc_Spell[381678] = "Reduces the cooldown of Spirit Walk by 10 sec.\n\nReduces the cooldown of Gust of Wind by 5 sec."
WordHunterWoW_ENDesc_Spell[381689] = "Stamina increased by 8%.\n\nWhile you are at full health, Reincarnation cools down 50% faster."
WordHunterWoW_ENDesc_Spell[381707] = "Increases your maximum Maelstrom by 50.\n\nIncreases Earth Shock, Elemental Blast, and Earthquake damage by 5%."
WordHunterWoW_ENDesc_Spell[381708] = "Reduces the Maelstrom cost of Earth Shock and Earthquake by 5.\n\nReduces the Maelstrom cost of Elemental Blast by 10."
