WordHunterWoW_ENDesc_Spell[383363] = "When mounted on a skyriding mount, double jump to launch upward and start gliding forward."
WordHunterWoW_ENDesc_Spell[383366] = "While skyriding at high speeds, your Skyriding Charges recharge faster."
WordHunterWoW_ENDesc_Spell[383388] = "Your haste is increased by 5%."
WordHunterWoW_ENDesc_Spell[383391] = "Fire Blast increases your mastery by 2% for 4 sec. Multiple applications may overlap."
WordHunterWoW_ENDesc_Spell[383396] = "Divine Storm projects an additional wave of light, striking all enemies up to 20 yds in front of you for 20% of Divine Storm's damage."
WordHunterWoW_ENDesc_Spell[383430] = "Critical strike damage of your abilities is increased by 10%."
WordHunterWoW_ENDesc_Spell[383442] = "Colossus Smash's duration is reduced by 20% but its damage bonus is increased by 20%."
WordHunterWoW_ENDesc_Spell[383459] = "Haste increased by 1% and Raging Blow and Bloodthirst generate an additional 1 Rage."
WordHunterWoW_ENDesc_Spell[383468] = "Enraged Regeneration lasts 3 sec longer and instantly heals for 10% of your maximum health."
WordHunterWoW_ENDesc_Spell[383486] = "While Enraged, your auto-attacks can no longer miss."
WordHunterWoW_ENDesc_Spell[383489] = "Your critical strike damage is increased by 3%. When you activate Combustion, you gain 2% additional critical strike damage, and up to 4 nearby allies gain 1% critical strike for 10 sec."
WordHunterWoW_ENDesc_Spell[383499] = "Consuming Hot Streak grants you 1% increased Intellect for 12 sec. This effect stacks up to 3 times."
WordHunterWoW_ENDesc_Spell[383604] = "Casting Scorch on targets below 30% health increase the target's damage taken from you by 7% for 12 sec. This effect stacks up to 2 times."
WordHunterWoW_ENDesc_Spell[383605] = "Increases auto-attack damage with one-handed weapons by 30% and your auto-attack critical strikes have a 50% chance to Enrage you."
WordHunterWoW_ENDesc_Spell[383634] = "While Combustion is active, Fire Blast recharges 50% faster."
WordHunterWoW_ENDesc_Spell[383649] = "Refines 5 Serevite Ore  to 1 Serevite Ore ."
WordHunterWoW_ENDesc_Spell[383659] = "Pyroblast has a 15% reduced cast time and a 10% increased critical strike chance. The duration of Combustion is reduced by 50%."
WordHunterWoW_ENDesc_Spell[383661] = "Increases Arcane Missiles damage by 5%."
WordHunterWoW_ENDesc_Spell[383665] = "Enemies damaged by Flame Patch have a 5% chance to erupt into a Living Bomb."
WordHunterWoW_ENDesc_Spell[383669] = "Damaging an enemy with Fireball, Pyroblast, or Flamestrike increases the damage it receives from Ignite by 0.2%. Stacks up to 50 times."
WordHunterWoW_ENDesc_Spell[383676] = "Arcane Blast generates an additional Arcane Charge."
WordHunterWoW_ENDesc_Spell[383695] = "Blackout Kick deals 20% increased damage."
WordHunterWoW_ENDesc_Spell[383697] = "When you use Keg Smash, the remaining cooldown on Breath of Fire is reset."
WordHunterWoW_ENDesc_Spell[383698] = "Keg Smash deals an additional 20% damage to targets affected by Breath of Fire."
WordHunterWoW_ENDesc_Spell[383700] = "Purifying Brew instantly heals you for 25% of the Staggered damage it clears."
WordHunterWoW_ENDesc_Spell[383703] = "Mortal Strike has a 50% chance to apply a Fatal Mark to your target, stacking up to 5 times. Your next Execute on a target with a Fatal Mark causes the Fatal Mark to deal 96 additional Physical damage per stack."
WordHunterWoW_ENDesc_Spell[383707] = "Keg Smash deals 50% additional damage to its primary target, has 1 additional charge, and its range is increased by 10 yards."
WordHunterWoW_ENDesc_Spell[383714] = "Gain up to 15% Mastery based on your current level of Stagger."
WordHunterWoW_ENDesc_Spell[383759] = "Crafting this may inspire you with the knowledge of another profession's Draconic Treatise."
WordHunterWoW_ENDesc_Spell[383762] = "Restores 20% health instantly and removes all diseases, poisons, and curses affecting you."
WordHunterWoW_ENDesc_Spell[383782] = "Consuming Clearcasting increases the damage of your next 2 Arcane Blasts or Arcane Barrages by 20%."
WordHunterWoW_ENDesc_Spell[383785] = "Each time you dodge or an enemy misses you, your next Tiger Palm or Spinning Crane Kick deals 100% increased damage."
WordHunterWoW_ENDesc_Spell[383792] = "Refines 5 Serevite Ore  to 1 Serevite Ore ."
WordHunterWoW_ENDesc_Spell[383793] = "Refines 5 Draconium Ore  to 1 Draconium Ore ."
WordHunterWoW_ENDesc_Spell[383795] = "Refines 5 Draconium Ore  to 1 Draconium Ore ."
WordHunterWoW_ENDesc_Spell[383796] = "Refines 5 Khaz'gorite Ore  to 1 Khaz'gorite Ore ."
WordHunterWoW_ENDesc_Spell[383797] = "Refines 5 Khaz'gorite Ore  to 1 Khaz'gorite Ore ."
WordHunterWoW_ENDesc_Spell[383810] = "Each consecutive critical strike you deal increases critical strike damage you deal by 1%, up to 4% for 6 sec."
WordHunterWoW_ENDesc_Spell[383848] = "Enrage increases your haste by 15% and your movement speed by 10%."
WordHunterWoW_ENDesc_Spell[383852] = "Bloodthirst and Raging Blow damage increased by 2.5% and critical strike damage increased by a further 2.5%."
WordHunterWoW_ENDesc_Spell[383854] = "Raging Blow has 2 charges and has a 25% chance to instantly reset its own cooldown."
WordHunterWoW_ENDesc_Spell[383860] = "While Combustion is not active, consuming Hot Streak has a low chance to cause all Pyroblasts and Flamestrikes to have no cast time and be guaranteed critical strikes for 5 sec. \n\nEach cast of Pyroblast or Flamestrike during Hyperthermia increases the damage of Pyroblast and Flamestrike by 15%, up to 150%."
WordHunterWoW_ENDesc_Spell[383877] = "Rampage has a 75% chance to refund a charge of Raging Blow and increase the damage of your next Raging Blow by 20%."
WordHunterWoW_ENDesc_Spell[383885] = "Bloodthirst deals 25% increased damage to enemies who are below 35% health."
WordHunterWoW_ENDesc_Spell[383886] = "After consuming 10 Hot Streaks, your next non-instant Pyroblast or Flamestrike cast within 30 sec grants you Combustion for 6 sec and deals 260% additional damage."
WordHunterWoW_ENDesc_Spell[383916] = "Your auto-attacks deal an additional 4 Physical damage and generate 2 Rage."
WordHunterWoW_ENDesc_Spell[383922] = "Recklessness lasts 4.0 sec longer."
WordHunterWoW_ENDesc_Spell[383959] = "Bloodthirst critical strikes generate 4 additional Rage and inflict a Gushing Wound that deals 42 Bleed damage over 6 sec and heals you for the damage dealt."
WordHunterWoW_ENDesc_Spell[383967] = "Combustion grants mastery equal to 75% of your Critical Strike stat.\n\nCombustion causes your spells to apply Ignite at 15% increased effectiveness."
WordHunterWoW_ENDesc_Spell[383980] = "Your Haste is increased by 2%."
WordHunterWoW_ENDesc_Spell[383994] = "Breath of Fire deals 100% increased damage, and after using Breath of Fire, you breathe fire 2 additional times, each dealing 7 Fire damage."
WordHunterWoW_ENDesc_Spell[384012] = "Increases the remaining stock of fish by 10."
WordHunterWoW_ENDesc_Spell[384027] = "After casting Divine Toll, you instantly cast Holy Shock every 5 sec for 15 sec."
WordHunterWoW_ENDesc_Spell[384033] = "Meteor gains a second charge, with a 15 sec cooldown between uses."
WordHunterWoW_ENDesc_Spell[384036] = "10% of damage you deal adds to your active Ignore Pain or the next Ignore Pain you activate.\n\nYour next Ignore Pain can be increased by up to 4,582."
WordHunterWoW_ENDesc_Spell[384041] = "Devastate, Thunder Clap, Revenge, and Execute have a 25% chance to reset the remaining cooldown on Shield Slam."
WordHunterWoW_ENDesc_Spell[384042] = "Last Stand increases your Rage generation by 50%."
WordHunterWoW_ENDesc_Spell[384060] = "Clearcasting has a 3% increased chance to proc."
WordHunterWoW_ENDesc_Spell[384063] = "Increases Stamina by 5% and your Haste by 2%."
WordHunterWoW_ENDesc_Spell[384067] = "Increases Strength by 3% and your critical strike chance by 1%."
WordHunterWoW_ENDesc_Spell[384069] = "Slows enemies in a 12 yard cone in front of you by 70% for 6 sec."
WordHunterWoW_ENDesc_Spell[384072] = "Shield Slam reduces the remaining cooldown of Shield Wall by 6 sec."
WordHunterWoW_ENDesc_Spell[384087] = "After casting Earth Shock, your next Earthquake deals 120% additional damage.\n\nAfter casting Elemental Blast, your next Earthquake deals 140% additional damage."
WordHunterWoW_ENDesc_Spell[384090] = "Throws your weapon at the enemy, causing 12 Physical damage to it and 5 nearby enemies. \n\nGenerates high threat."
WordHunterWoW_ENDesc_Spell[384100] = "Go berserk, removing and granting immunity to Fear, Sap, and Incapacitate effects for 6 sec.\n\nAlso remove fear effects from group members within 12 yds."
WordHunterWoW_ENDesc_Spell[384110] = "Hurl your weapon at the enemy, causing 210 Physical damage, ignoring armor. Deals up to 500% increased damage to absorb shields."
WordHunterWoW_ENDesc_Spell[384124] = "Gain Strength equal to 5% of your Armor."
WordHunterWoW_ENDesc_Spell[384143] = "Maelstrom Weapon can now stack 5 additional times.\n\nEach Maelstrom Weapon stacks consumed grants Overflowing Maelstrom, reducing the cast time of your next Healing Surge or Chain Heal by 10%, and increasing their healing by 10% up to 10 times. This effect can be accumulated up to 20 times."
WordHunterWoW_ENDesc_Spell[384149] = "Lightning Bolt and Chain Lightning can consume up to 10 Maelstrom Weapon stacks."
WordHunterWoW_ENDesc_Spell[384174] = "Ignite deals 15% more damage when Combustion is not active.\n\nFire Blast now spreads an additional 50% of your Ignite."
WordHunterWoW_ENDesc_Spell[384187] = "Evocation grants 1 Arcane Charge, channels 50% faster and while channeling Evocation, your Intellect is increased by 2% every 0.4 sec. Lasts 20 sec."
WordHunterWoW_ENDesc_Spell[384276] = "Consuming a Mana Gem grants up to 2 Clearcasting stacks."
WordHunterWoW_ENDesc_Spell[384277] = "Thunder Clap affects all targets with Rend, causing them to Bleed for 74 damage over 15 sec."
WordHunterWoW_ENDesc_Spell[384318] = "Roar explosively, dealing 88 Physical damage to enemies within 12 yds and cause them to bleed for 98 physical damage over 8 sec. Deals reduced damage beyond 5 targets."
WordHunterWoW_ENDesc_Spell[384352] = "Unleash a devastating storm around yourself, dealing 42 Stormstrike damage every 1 sec to nearby enemies for 8 sec.\n\nIncreases your chance to activate Windfury Weapon by 50%, and the damage of Windfury Weapon by 20%."
WordHunterWoW_ENDesc_Spell[384355] = "Each active weapon imbue increases all Fire, Frost, and Nature damage dealt by 5.0%."
WordHunterWoW_ENDesc_Spell[384359] = "Consuming at least 2 stacks of Hailstorm, and each explosion from Fire Nova now also grants you 1 stack of Maelstrom Weapon."
WordHunterWoW_ENDesc_Spell[384361] = "Damage from Rend has a chance to generate 5 Rage."
WordHunterWoW_ENDesc_Spell[384363] = "Each target hit by Crash Lightning increases the damage of your next Stormstrike by 25%, up to a maximum of 6 stacks."
WordHunterWoW_ENDesc_Spell[384374] = "Arcane Blast has a small chance to make your next cast of Arcane Blast free."
WordHunterWoW_ENDesc_Spell[384376] = "Call upon the Light and become an avatar of retribution, increasing your damage and healing done by 0% for 20 sec, and allowing Hammer of Wrath to be cast on any target.\n\nCombines with other Avenging Wrath abilities, granting all known Avenging Wrath effects while active."
WordHunterWoW_ENDesc_Spell[384404] = "Your auto-attacks have a 20% chance to hurl weapons at your target and 1 other enemy in front of you, dealing 24 Physical damage."
WordHunterWoW_ENDesc_Spell[384405] = "Primordial Wave generates 3 stacks of Maelstrom Weapon."
WordHunterWoW_ENDesc_Spell[384411] = "During Doom Winds or Ascendance, you generate 1 Maelstrom Weapon stack every 1 sec."
WordHunterWoW_ENDesc_Spell[384444] = "Doom Winds and Deeply Rooted Elements last 2 sec longer, and the cooldown of Ascendance is reduced by 60 sec.\n\nDuring Doom Winds or Ascendance, Stormstrike and Crash Lightning consume up to 10 Maelstrom Weapon to discharge a Lightning Bolt or Chain Lightning at 100% effectiveness at your enemy, whichever you most recently used."
WordHunterWoW_ENDesc_Spell[384447] = "Increases the chance to gain a stack of Maelstrom Weapon by 4%, and whenever you gain a stack of Maelstrom Weapon, the cooldown of Feral Spirits is reduced by 1.0 sec."
WordHunterWoW_ENDesc_Spell[384450] = "Consuming 10 stacks of Maelstrom Weapon increases the damage of your next Stormstrike or Lava Lash by 25% and causes them to generate a stack of Maelstrom Weapon."
WordHunterWoW_ENDesc_Spell[384452] = "Each wave of Arcane Missiles increases the damage of Arcane Barrage by 3%, up to 60%."
WordHunterWoW_ENDesc_Spell[384565] = "Versatility increased by 6."
WordHunterWoW_ENDesc_Spell[384581] = "Arcane Barrage deals an additional 100% damage against targets below 35% health."
WordHunterWoW_ENDesc_Spell[384583] = "When you are stunned, harden your resolve, absorbing up to 1,933 damage for 10 sec. Cannot occur more than once every 2 min."
WordHunterWoW_ENDesc_Spell[384612] = "Arcane Charges increase the damage of Arcane Blast and Arcane Barrage by an additional 10%."
WordHunterWoW_ENDesc_Spell[384651] = "Arcane Orb gains 1 additional charge. Arcane Orb damage increased by 15%."
WordHunterWoW_ENDesc_Spell[384656] = "Moonfire increases your Arcane damage to the target, and Sunfire increases your Nature damage to the target, by 1%."
WordHunterWoW_ENDesc_Spell[384665] = "Ferocious Bite deals 16% increased damage and an additional 8% during Tiger's Fury."
WordHunterWoW_ENDesc_Spell[384667] = "Finishing moves have a 6% chance per combo point spent to increase the direct damage of your next Rake, Shred, or Swipe by 50% and make it critically strike."
WordHunterWoW_ENDesc_Spell[384683] = "Damage dealt to enemies affected by Radiant Spark's vulnerability echo to your current enemy target and 4 nearby enemies for 20% of the damage dealt."
WordHunterWoW_ENDesc_Spell[384689] = "Deep Breath forms curtains of fire, preventing line of sight to enemies outside its walls and burning enemies who walk through them for 2,736 Fire damage. Lasts 6 sec."
WordHunterWoW_ENDesc_Spell[384790] = "After gaining Deathblow, your next Kill Shot will deal 75% increased damage, and shred up to 5 targets near your Kill Shot target for 35% of the damage dealt by Kill Shot over 6 sec."
WordHunterWoW_ENDesc_Spell[384799] = "Damage taken from area of effect attacks reduced by 5%."
WordHunterWoW_ENDesc_Spell[384815] = "When you cast Word of Glory on someone other than yourself, you are also healed for 100% of the amount healed."
WordHunterWoW_ENDesc_Spell[384820] = "Reduces the cooldown of Blessing of Sacrifice by 60 sec."
WordHunterWoW_ENDesc_Spell[384824] = "While airborne on a Skyriding mount, you gain stacks of Skyrider's Compassion, up to 10. \n\nWhen you dismount, you gain a shield worth 1% of your health and gain 1% movement speed per stack, lasting 30 sec"
WordHunterWoW_ENDesc_Spell[384858] = "Arcane Barrage has a 4% chance per stack of Arcane Salvo to launch an Arcane Orb in front of you at 100% effectiveness."
WordHunterWoW_ENDesc_Spell[384861] = "Standing still for 10 sec grants you Foresight, allowing you to cast while moving for 4 sec. This duration begins when you start moving."
WordHunterWoW_ENDesc_Spell[384897] = "Golden Path strikes the lowest health ally within it an additional time for 100% of its effect."
WordHunterWoW_ENDesc_Spell[384909] = "Reduces the cooldown of Blessing of Protection by 60 sec."
WordHunterWoW_ENDesc_Spell[384914] = "After your Blessing of Sacrifice ends, 50% of the total damage it diverted is added to your next Judgment as bonus damage, or your next Word of Glory as bonus healing.\n\nThis effect's bonus damage cannot exceed 30% of your maximum health and its bonus healing cannot exceed 100% of your maximum health."
WordHunterWoW_ENDesc_Spell[384969] = "Increases the duration of Thunderous Roar's Bleed effect by 2.0 sec and Thunderous Roar's Bleed effect causes enemies to take 20% increased damage from all your bleeds."
WordHunterWoW_ENDesc_Spell[385008] = "When Colossus Smash expires, your Strength is increased by 1% for every 10 Rage you spent on attacks during Colossus Smash. Lasts 12 sec."
WordHunterWoW_ENDesc_Spell[385059] = "Unleashes your power, dealing 135 Physical damage and an additional 182 Bleed damage over 4 sec to all enemies within 12 yards. Deals reduced damage beyond 8 targets.\n\nEnrages you and generates 20 Rage."
WordHunterWoW_ENDesc_Spell[385125] = "When you cast 3 Holy Power generating abilities, you gain Blessing of Dawn. When you consume Blessing of Dawn, you gain Blessing of Dusk.\n\nBlessing of Dawn\nYour next Holy Power spending ability deals 30% additional increased damage and healing. This effect stacks.\n\nBlessing of Dusk\nDamage taken reduced by 4% For 10 sec."
WordHunterWoW_ENDesc_Spell[385129] = "Blessing of Dawn:\nBlessing of Dawn increases the damage and healing of your next Holy Power spending ability by an additional 10%.\n\nBlessing of Dusk:\nBlessing of Dusk increases your armor by 10% and your Holy Power generating abilities cooldown 10% faster."
WordHunterWoW_ENDesc_Spell[385167] = "Casting Frozen Orb grants 1 stack of Fingers of Frost.\n\nDamaging one or more enemies with Frozen Orb has a 3% chance to grant Fingers of Frost."
WordHunterWoW_ENDesc_Spell[385274] = "Unlocks the ability to read Drakewatcher Manuscripts, which unlock Dragon Isles drake customization options at Rostrums of Transformation."
WordHunterWoW_ENDesc_Spell[385349] = "Your spells and abilities have a chance to cause your target to erupt in a blinding light dealing 10 Holy damage or healing an ally for 15 health."
WordHunterWoW_ENDesc_Spell[385408] = "Infect the target's blood, dealing 147 Nature damage over 10 sec and gaining 1 use of any Stealth ability. If the target survives its full duration, they suffer an additional 51 damage and you gain 1 additional use of any Stealth ability for 10 sec.\n\nCooldown reduced by 30 sec if Sepsis does not last its full duration.\n\nAwards 1 combo point."
WordHunterWoW_ENDesc_Spell[385414] = "After you spend 20 Holy Power, your next Word of Glory echoes onto a nearby ally at 30% effectiveness."
WordHunterWoW_ENDesc_Spell[385416] = "Your Crusader Strike now also grants you 1% increased Intellect for 6 sec. Multiple applications may overlap."
WordHunterWoW_ENDesc_Spell[385420] = "Killing enemy players grants Breaker's Frenzy, increasing versatility by 2% and movement speed by 2%. Can stack up to 10 times."
WordHunterWoW_ENDesc_Spell[385424] = "Embed a bone spike in the target, dealing 61 Physical damage and 6 Bleed damage every 2.7 sec until they die or leave combat. \n\nRefunds a charge when target dies.\n\nAwards 1 combo point plus 1 additional per active bone spike."
WordHunterWoW_ENDesc_Spell[385425] = "Haste increased by 2% and Judgment cooldown reduced by 0.5 sec."
WordHunterWoW_ENDesc_Spell[385427] = "Speed increased by 2% and damage taken from area of effect attacks reduced by 2%."
WordHunterWoW_ENDesc_Spell[385450] = "Mastery increased by 2% and Intellect increased by 2%."
WordHunterWoW_ENDesc_Spell[385478] = "Garrote damage increased by 30%. Garrote generates 2 additional combo points when used from Stealth."
WordHunterWoW_ENDesc_Spell[385512] = "Cleave and Whirlwind have a 30% chance to make your next Cleave or Whirlwind cost 100% less Rage."
WordHunterWoW_ENDesc_Spell[385515] = "Armor and critical strike chance increased by 4%."
WordHunterWoW_ENDesc_Spell[385539] = "Exhilaration now also heals you for an additional 12.0% of your maximum health over 8 sec."
WordHunterWoW_ENDesc_Spell[385571] = "Overpower has 2 charges and deals 15% more damage."
WordHunterWoW_ENDesc_Spell[385573] = "Damage of Mortal Strike increased by 15%."
WordHunterWoW_ENDesc_Spell[385627] = "Release a powerful poison from your weapons and inject it into your target, dealing 51 Nature damage instantly and an additional 71 Nature damage over 14 sec. \n\nEach time you apply a Lethal Poison to a target affected by Kingsbane, Kingsbane damage increases by 20%, up to 1,000%.\n\nAwards 1 combo point."
WordHunterWoW_ENDesc_Spell[385633] = "Learn Concentration Aura, Devotion Aura, and Crusader Aura:\n\nConcentration Aura:\nInterrupt and Silence effects on party and raid members within 40 yds are 30% shorter. \n\n Devotion Aura:\nParty and raid members within 40 yds are bolstered by their devotion, reducing damage taken by 3%.\n\n Crusader Aura:\nIncreases mounted speed by 20% for all party and raid members within 40 yds."
WordHunterWoW_ENDesc_Spell[385695] = "Kill Shot, Serpent Sting, Arcane Shot, Steady Shot, and Explosive Shot deal 20% increased damage."
WordHunterWoW_ENDesc_Spell[385696] = "Empower spells cause time to flow 10% faster for you, increasing movement speed, cooldown recharge rate, and cast speed. Lasts 10 sec."
WordHunterWoW_ENDesc_Spell[385703] = "Bloodthirst causes your Bleeds to deal 20% additional damage for 8 sec."
WordHunterWoW_ENDesc_Spell[385704] = "Your Bleed effects deal 25% increased damage."
WordHunterWoW_ENDesc_Spell[385709] = "Kill Command generates 6 additional Focus."
WordHunterWoW_ENDesc_Spell[385718] = "Fury of the Eagle now gains bonus critical strike chance against targets below 35% health, and Fury of the Eagle critical strikes reduce the cooldown of Wildfire Bomb and Flanking Strike by 1.0 sec."
WordHunterWoW_ENDesc_Spell[385722] = "Gaining Stealth, Vanish, or Shadow Dance causes your next Shuriken Storm to have 100% increased chance to critically strike."
WordHunterWoW_ENDesc_Spell[385728] = "Your auto attacks deal 18 additional Holy damage."
WordHunterWoW_ENDesc_Spell[385737] = "Each stack of Mongoose Fury also increases the damage of Strike as One by 10%."
WordHunterWoW_ENDesc_Spell[385739] = "While Coordinated Assault is active, the cooldown of Wildfire Bomb is reduced by 25%, Wildfire Bomb generates 5 Focus when thrown, Kill Shot's cooldown is reduced by 25%, and Kill Shot can be used against any target, regardless of their current health."
WordHunterWoW_ENDesc_Spell[385786] = "When you use Barkskin or Survival Instincts, absorb 656 damage for 15 sec."
WordHunterWoW_ENDesc_Spell[385810] = "Dire Beast lasts an additional 1 sec and deals 10% increased damage."
WordHunterWoW_ENDesc_Spell[385840] = "Increases the radius of Demoralizing Shout by 5 yards.\n\nEach enemy hit by Thunder Clap reduces the remaining cooldown on Demoralizing Shout by 1.5 sec, up to 4.5 sec."
WordHunterWoW_ENDesc_Spell[385843] = "Revenge damage increased by 10% and Revenge increases the damage of your next Thunder Clap by 20%."
WordHunterWoW_ENDesc_Spell[385881] = "Your primary pets gain a bonus effect.\n\nImp: Successful Singe Magic casts grant the target 4% damage reduction for 5 sec.\n\nVoidwalker: Reduces the cooldown of Shadow Bulwark by 30 sec.\n\nFelhunter: Reduces the cooldown of Devour Magic by 5 sec.\n\nSayaad: Reduces the cooldown of Seduction by 10 sec and causes the target to walk faster towards the demon."
WordHunterWoW_ENDesc_Spell[385888] = "Blocking an attack deals 42 Physical damage to the attacker. Critical blocks deal double damage.\n\nGenerates high threat."
WordHunterWoW_ENDesc_Spell[385899] = "Consumes a Soul Shard, unlocking the hidden power of your spells.\n\nDemonic Circle: Teleport: Increases your movement speed by 50% and makes you immune to snares and roots for 6 sec.\n\nDemonic Gateway: Can be cast instantly.\n\nDrain Life: Gain an absorb shield equal to the amount of healing done for 30 sec. This shield cannot exceed 30% of your maximum health.\n\nHealthstone: Increases the healing of your Healthstone by 30% and increases your maximum health by 20% for 12 sec."
WordHunterWoW_ENDesc_Spell[385923] = "Increases the Maelstrom generated by Lightning Bolt and Lava Burst by 2."
WordHunterWoW_ENDesc_Spell[385952] = "Charge to an enemy with your shield, granting you Shield Block and dealing 294 Physical damage to it and 94 Physical damage to all enemies within 10 yards.\n\nAlso stuns the primary target for 4 sec.\n\nGenerates 20 Rage."
WordHunterWoW_ENDesc_Spell[386011] = "Increases Block chance by 8% and your Block value by 16%."
WordHunterWoW_ENDesc_Spell[386027] = "Shield Block lasts 1 sec longer."
WordHunterWoW_ENDesc_Spell[386030] = "Using Shield Slam increases the damage of Shield Slam by 10% and the block value of your shield by 5% for 16 sec. Stacking up to 3 times."
WordHunterWoW_ENDesc_Spell[386071] = "Taunts all enemies within 14 yds to attack you for 6 sec, interrupts all spellcasting within 14 yds and prevents any spell in that school from being cast for 6 sec. Increases the threat you generate against the target by 800%."
WordHunterWoW_ENDesc_Spell[386105] = "Grants access to the following abilities:\n\nCurse of Tongues:\nForces the target to speak in Demonic, increasing the casting time of all spells by 30% for 1 min.\n\nCurses: A warlock can only have one Curse active per target.\n\nCurse of Exhaustion:\nReduces the target's movement speed by 50% for 12 sec.\n\nCurses: A warlock can only have one Curse active per target."
WordHunterWoW_ENDesc_Spell[386110] = "Reduces the damage dealt by Burning Rush by 10%. Burning Rush increases your movement speed by an additional 20%."
WordHunterWoW_ENDesc_Spell[386113] = "Reduces the cooldown of Fel Domination by 60 sec."
WordHunterWoW_ENDesc_Spell[386124] = "When Soul Leech absorbs damage, 5% of damage taken is absorbed and spread out over 5 sec.\n\nReduces damage taken by 1.5%."
WordHunterWoW_ENDesc_Spell[386164] = "A balanced combat state that increases the critical strike chance of your abilities by 3% and reduces the duration of movement impairing effects by 10%. \n\nLasts until canceled."
WordHunterWoW_ENDesc_Spell[386174] = "Your Felguard deals 20% more damage and takes 10% less damage."
WordHunterWoW_ENDesc_Spell[386185] = "Hand of Gul'dan has a 5% chance to generate a charge of Demonic Core."
WordHunterWoW_ENDesc_Spell[386194] = "Your Dreadstalkers' attacks have a 10% chance to trigger an additional Dreadbite."
WordHunterWoW_ENDesc_Spell[386196] = "An aggressive combat state that increases the damage of your auto-attacks by 15% and reduces the duration of Fear, Sap and Incapacitate effects on you by 10%.\n\nLasts until canceled."
WordHunterWoW_ENDesc_Spell[386200] = "Your primary Felguard's Legion Strike damage is increased by 10%. \n\nYour primary Felguard's Felstorm damage is increased by 5%."
WordHunterWoW_ENDesc_Spell[386208] = "A defensive combat state that reduces all damage you take by 15% and all damage you deal by 10%.\n\nLasts until canceled."
WordHunterWoW_ENDesc_Spell[386256] = "Summons a Soulkeeper that consumes all Tormented Souls you've collected, blasting nearby enemies for 21 Chaos damage per soul consumed over 8 sec. Deals reduced damage beyond 8 targets and only one Soulkeeper can be active at a time.\n\nYou collect Tormented Souls from each target you kill and occasionally escaped souls you previously collected."
WordHunterWoW_ENDesc_Spell[386272] = "Essence Burst increases the damage of affected spells by 15.0%."
WordHunterWoW_ENDesc_Spell[386276] = "Hurl a brew created from the bones of your enemies at the ground, coating all targets struck for 10 sec. Your abilities have a 50% chance to affect the target a second time at 40% effectiveness as Shadow damage or healing."
WordHunterWoW_ENDesc_Spell[386283] = "While channeling Disintegrate your Fire Breath on the target deals damage 100% more often."
WordHunterWoW_ENDesc_Spell[386284] = "The duration of Champion's Spear is increased by 2 sec. You deal 82% increased critical strike damage to targets chained to your Spear."
WordHunterWoW_ENDesc_Spell[386328] = "Shield Charge deals 20% increased damage, grants you Shield Block, and makes your next Revenge cost no Rage."
WordHunterWoW_ENDesc_Spell[386344] = "Your spells and abilities have a chance to summon an Inquisitor's Eye that deals 226 Shadowflame damage every 0.9 sec for 13.4 sec."
WordHunterWoW_ENDesc_Spell[386348] = "Deep Breath's cooldown is reduced by 1 min."
WordHunterWoW_ENDesc_Spell[386357] = "Skullsplitter deals 30% increased damage and also causes your Rend on the target to bleed out 100% faster for 10 sec."
WordHunterWoW_ENDesc_Spell[386394] = "When your health is brought below 30%, you take 80% less damage for 8 sec and healing you receive is increased by 100%.\n\nCannot occur more than once every 3 min."
WordHunterWoW_ENDesc_Spell[386405] = "Your Living Flame and Emerald Blossom are 30% more effective on yourself."
WordHunterWoW_ENDesc_Spell[386443] = "Lava Burst and Lava Burst Overload damage reduces the cooldown of Primordial Wave by 1.0 sec."
WordHunterWoW_ENDesc_Spell[386474] = "Casting Primordial Wave triggers Lava Surge immediately and every 3 sec for 12 sec. Lava Surges triggered by Primordial Wave increase the damage of your next Lava Burst by 15%."
WordHunterWoW_ENDesc_Spell[386477] = "Every 250 rage you spend triggers a Violent Outburst, causing your next Shield Slam to deal 200% increased damage, generate 50% more Rage and grant Ignore Pain."
WordHunterWoW_ENDesc_Spell[386485] = "Unlocks access to the Ancient Waygate travel network."
WordHunterWoW_ENDesc_Spell[386539] = "While you have Temporal Displacement or other similar effects, you may use Time Warp to grant yourself 30% Haste for 40 sec."
WordHunterWoW_ENDesc_Spell[386613] = "Drain Life heals for 15% of the amount drained over 8.9 sec."
WordHunterWoW_ENDesc_Spell[386617] = "Increases you and your pets' maximum health by 5%."
WordHunterWoW_ENDesc_Spell[386619] = "Drain Life heals for 15% more while below 50% health."
WordHunterWoW_ENDesc_Spell[386620] = "Your Healthstone heals you for an additional 10% of your maximum health. Any party or raid member using a Healthstone also heals you for that amount."
WordHunterWoW_ENDesc_Spell[386628] = "Every 2 strikes of Bladestorm, you automatically cast a Mortal Strike at your target or random nearby enemy, dealing 100% of normal damage."
WordHunterWoW_ENDesc_Spell[386630] = "Overpower has a 35% chance to reset the cooldown of Mortal Strike and reduce the cost of your next Mortal Strike by 33%."
WordHunterWoW_ENDesc_Spell[386634] = "Execute increases the damage of your next Mortal Strike by 35%, stacking up to 2 times."
WordHunterWoW_ENDesc_Spell[386646] = "When you use a Healthstone, gain 4% Leech for 20 sec."
WordHunterWoW_ENDesc_Spell[386648] = "Increases the amount of damage required to break your fear effects by 60%."
WordHunterWoW_ENDesc_Spell[386651] = "Increases the duration of Banish by 30 sec. Banish now affects Undead."
WordHunterWoW_ENDesc_Spell[386653] = "Avenger's Shield increases the damage of your next Shield of the Righteous by 10% for each target hit by Avenger's Shield, stacking up to 5 times, and increases its radius by 6 yds."
WordHunterWoW_ENDesc_Spell[386659] = "Reduces the cooldown of Unending Resolve by 45 sec."
WordHunterWoW_ENDesc_Spell[386664] = "Dark Pact sacrifices only 5% of your current health for the same shield value."
WordHunterWoW_ENDesc_Spell[386686] = "Reduces the cooldown of Dark Pact by 15 sec."
WordHunterWoW_ENDesc_Spell[386689] = "Healthstones you conjure for yourself are now Demonic Healthstones and can be used multiple times in combat. Demonic Healthstones cannot be traded.\n\n Demonic Healthstone\nInstantly restores 25% health. 60 sec cooldown."
WordHunterWoW_ENDesc_Spell[386696] = "Hurl bolts of decimating magic at your target, dealing 5,581 Shadow damage and increasing the damage of your next 3 Shadow Bolts or Drain Souls by 40%.\n\nDecimating Bolt's damage, and the bonus to Shadow Bolt and Drain Soul both increase as your target's health decreases."
WordHunterWoW_ENDesc_Spell[386738] = "After casting Holy Prism, Holy Armament, or Divine Toll, you instantly cast Holy Shock every 5 sec for 15 sec."
WordHunterWoW_ENDesc_Spell[386759] = "Refreshing Corruption, Agony, Unstable Affliction, or Siphon Life with less than 5 seconds remaining will deal 182 Shadow damage and has a 6.66% chance to grant you a Soul Shard."
WordHunterWoW_ENDesc_Spell[386763] = "Enemies hit by Cone of Cold are frozen in place for 5 sec instead of snared.\n\nWhen your roots expire or are dispelled, your target is snared by 80%, decaying over 3 sec."
WordHunterWoW_ENDesc_Spell[386828] = "Casting your barrier removes all snare effects."
WordHunterWoW_ENDesc_Spell[386833] = "Your Felguard hurls his axe towards the target location, erupting when it lands and dealing 142 Shadowflame damage every 1 sec for 6 sec to nearby enemies.\n\nWhile unarmed, your Felguard's basic attacks deal damage to all nearby enemies and attacks 50% faster."
WordHunterWoW_ENDesc_Spell[386858] = "Increases the attack speed of your primary pet by 5%. \n\nIncreases Grimoire of Sacrifice damage by 10%."
WordHunterWoW_ENDesc_Spell[386864] = "Increases the damage done by your primary pet by 5%. \n\nIncreases Grimoire of Sacrifice damage by 10%."
WordHunterWoW_ENDesc_Spell[386870] = "Barbed Shot has a 25% chance to cause your pet to use its special attack and deal 50% bonus damage."
WordHunterWoW_ENDesc_Spell[386878] = "While Trueshot is active you gain 1% critical strike chance and 2% increased critical damage dealt every 1 sec, stacking up to 10 times."
WordHunterWoW_ENDesc_Spell[386887] = "Increases the remaining stock of fish by 20."
WordHunterWoW_ENDesc_Spell[386922] = "Seed of Corruption's explosion increases the stack count of Agony by 1 on all targets hit."
WordHunterWoW_ENDesc_Spell[386937] = "Each time you dodge or an enemy misses you, the remaining cooldown on your Brews is reduced by 0.5 sec. Effect reduced by 50% for each additional recent attacker, up to 5."
WordHunterWoW_ENDesc_Spell[386941] = "Bonedust Brew's Shadow damage or healing is increased by 20%, and when Bonedust Brew deals Shadow damage or healing, its cooldown is reduced by 0.5 sec."
WordHunterWoW_ENDesc_Spell[386949] = "Your abilities have a low chance to cast Bonedust Brew at your target's location."
WordHunterWoW_ENDesc_Spell[386951] = "Copies your damage over time effects and Haunt from the target, preserving their duration.\n\nYour next use of Soul Swap within 10 sec will exhale a copy damage of the effects onto a new target."
WordHunterWoW_ENDesc_Spell[386965] = "Your Breath of Fire ignites your right leg in flame for 8 sec, causing your Blackout Kick and Spinning Crane Kick to deal 50% additional damage as Fire damage and refresh the duration of your Breath of Fire on the target."
WordHunterWoW_ENDesc_Spell[386976] = "Shadow Bolt and Drain Soul deal 5% increased damage, up to 15%, per damage over time effect you have active on the target."
WordHunterWoW_ENDesc_Spell[386986] = "Corruption damage is increased by 15%, and each time it deals damage any of your Curses active on the target are extended by 0.5 sec."
WordHunterWoW_ENDesc_Spell[386997] = "Wither away all life force of your current target and up to 4 additional targets nearby, causing your primary target to suffer 2,621 Shadow damage and secondary targets to suffer 1,310 Shadow damage over 8 sec.\n\nDamage dealt by Soul Rot heals you for 50% of damage done."
WordHunterWoW_ENDesc_Spell[387016] = "Each target affected by Soul Rot increases your haste and critical strike chance by 4.0% for 8 sec."
WordHunterWoW_ENDesc_Spell[387035] = "Zen Meditation has 25% reduced cooldown and is no longer cancelled when you move or when you are hit by melee attacks."
WordHunterWoW_ENDesc_Spell[387044] = "Fire Blast gains 1 additional charge and its damage is increased by 25%."
WordHunterWoW_ENDesc_Spell[387046] = "Blackout Kick deals an additional 5% damage. Blackout Kick critical hits grant an additional 1 stack of Elusive Brawler."
WordHunterWoW_ENDesc_Spell[387065] = "Corruption and Agony each grant an application of Wrath of Consumption when a target dies, increasing all periodic damage dealt by 3% for 30 sec, stacking up to 5 times."
WordHunterWoW_ENDesc_Spell[387075] = "While Agony, Corruption, and Unstable Affliction are active, your Shadow Bolt has a 30% chance and your Drain Soul has a 20% chance to make your next Malefic Rapture cost no Soul Shards and cast instantly."
WordHunterWoW_ENDesc_Spell[387084] = "Summon Infernal cooldown is reduced by 60 sec."
WordHunterWoW_ENDesc_Spell[387093] = "Increases the duration of Immolate by 3 sec."
WordHunterWoW_ENDesc_Spell[387095] = "Enemies affected by your Rain of Fire take 3% increased damage from your Fire spells."
WordHunterWoW_ENDesc_Spell[387103] = "Increases the critical strike damage of your Destruction spells by 15%."
WordHunterWoW_ENDesc_Spell[387108] = "Conflagrate and Shadowburn have a 100% chance to critical strike and their damage is increased by your critical strike chance."
WordHunterWoW_ENDesc_Spell[387153] = "Chaos Bolt and Rain of Fire increase the damage of your next 2 Incinerates by 15%. Shadowburn increases the damage of your next Incinerate by 15%.\n\nStacks up to 6 times."
WordHunterWoW_ENDesc_Spell[387156] = "Every 20 Soul Shards spent grants Ritual of Ruin, making your next Chaos Bolt or Rain of Fire consume no Soul Shards and have its cast time reduced by 50%."
WordHunterWoW_ENDesc_Spell[387159] = "When Chaos Bolt or Rain of Fire consumes a charge of Ritual of Ruin, you summon a Blasphemy for 8 sec.\n\n Blasphemy\nSummons a Blasphemy from the Twisting Nether, impacting for 231 Fire damage and stunning all enemies in the area for 2 sec.\n\nThe Blasphemy will serve you for 8 sec, dealing 220 damage to all nearby enemies every 1.8 sec and generating 1 Soul Shard Fragment every 1 sec."
WordHunterWoW_ENDesc_Spell[387165] = "Ritual of Ruin requires 5 less Soul Shards spent."
WordHunterWoW_ENDesc_Spell[387166] = "Channel Demonfire fires an additional 2 bolts. Each bolt increases the remaining duration of Immolate on all targets hit by 0.5 sec."
WordHunterWoW_ENDesc_Spell[387168] = "Call upon the Covenants of the Shadowlands to aid you, restoring 2,280 health and increasing your Versatility by 10% for 12 sec.\n\nPassive: The Covenants have granted you a portion of their power, increasing your damage and healing by 4.0%."
WordHunterWoW_ENDesc_Spell[387170] = "Avenging Wrath empowers your next Word of Glory to automatically activate Light of Dawn with 25% increased effectiveness."
WordHunterWoW_ENDesc_Spell[387173] = "Incinerate now generates 100% additional Soul Shard Fragments."
WordHunterWoW_ENDesc_Spell[387176] = "Your Incinerate and Conflagrate casts on targets that have 35% or less health reduce the cooldown of Soulfire by 5 sec and reduce its cast time by 40% for 10 sec."
WordHunterWoW_ENDesc_Spell[387184] = "For the next 30 sec, your Mastery is increased by 9%. Additionally,"
WordHunterWoW_ENDesc_Spell[387198] = "Boon of the Covenants passively increases your damage and healing by an additional 1.0%."
WordHunterWoW_ENDesc_Spell[387201] = "Increases critical strike chance by 1.0%."
WordHunterWoW_ENDesc_Spell[387202] = "Increases mastery by 1.3%."
WordHunterWoW_ENDesc_Spell[387219] = "Your damaging abilities have a chance to invoke Niuzao, causing him to charge to your target's location and Stomp, dealing 139 Physical damage to your target and reduced damage to secondary targets."
WordHunterWoW_ENDesc_Spell[387222] = "Increases haste by 1.0%."
WordHunterWoW_ENDesc_Spell[387225] = "Increases your maximum health by 4.0%."
WordHunterWoW_ENDesc_Spell[387227] = "Reduces magic damage taken by 2.0%."
WordHunterWoW_ENDesc_Spell[387228] = "Increases leech by 2.0%."
WordHunterWoW_ENDesc_Spell[387230] = "Blackout Kick's cooldown is reduced by 1 sec."
WordHunterWoW_ENDesc_Spell[387240] = "Increases movement speed by 3.0%."
WordHunterWoW_ENDesc_Spell[387250] = "Haunt deals 10% additional damage. When the Haunt spell ends or is dispelled, the soul returns to you, healing for 50% of the damage it did to the target."
WordHunterWoW_ENDesc_Spell[387252] = "Chaos Bolt, Shadowburn, and Incinerate deal 3% increased damage to targets afflicted by Immolate."
WordHunterWoW_ENDesc_Spell[387256] = "After you successfully dodge or an enemy misses you, you gain 10% increased movement speed for 3 sec. Max 3 stacks."
WordHunterWoW_ENDesc_Spell[387259] = "When your Immolate deals periodic damage to a target above 80% health, gain 2% Haste for 10 sec.\n\nStacks up to 3 times."
WordHunterWoW_ENDesc_Spell[387267] = "Reduces the cooldown of Wing Buffet and Tail Swipe by 6 sec."
WordHunterWoW_ENDesc_Spell[387270] = "Increases the duration of Permeating Chill by 1.0 sec."
WordHunterWoW_ENDesc_Spell[387273] = "Increases the damage of your Darkglare by 70%. When Darkglare extends damage over time effects it also sears affected targets for 3,003 Shadow damage."
WordHunterWoW_ENDesc_Spell[387275] = "Chaos Bolt, Rain of Fire, and Shadowburn always gain at least 70% of the maximum benefit from your Mastery: Chaotic Energies."
WordHunterWoW_ENDesc_Spell[387276] = "Expel Harm's healing is increased by up to 100%, based on your missing health."
WordHunterWoW_ENDesc_Spell[387279] = "Consuming Soul Shards increases your Mastery by 0.5% for 10 sec for each shard spent. Gaining a stack does not refresh the duration."
WordHunterWoW_ENDesc_Spell[387301] = "Your Haunt spell also increases the damage of your damage over time effects to all targets by 20% while active."
WordHunterWoW_ENDesc_Spell[387322] = "When your summoned Dreadstalkers fade away, they increase the damage of your Demonbolt by 10% for 8 sec."
WordHunterWoW_ENDesc_Spell[387341] = "Wing Buffet and Tail Swipe knock enemies further and daze them, reducing movement speed by 70% for 4 sec."
WordHunterWoW_ENDesc_Spell[387349] = "The chance of receiving a Demonic Core from a Wild Imp is increased by 5% or 10% when imploded."
WordHunterWoW_ENDesc_Spell[387355] = "Summon Infernal reduces the Soul Shard cost of your next 3 casts of Chaos Bolt, Shadowburn, or Rain of Fire by 1."
WordHunterWoW_ENDesc_Spell[387384] = "Increases your critical strike chance by 2%.\n\nPhysical attacks against you have a 20% chance to make your next Incinerate instant cast. This effect can only occur once every 6 sec."
WordHunterWoW_ENDesc_Spell[387391] = "Each Soul Shard spent on Hand of Gul'dan increases the damage of your next Call Dreadstalkers by 2%."
WordHunterWoW_ENDesc_Spell[387399] = "Each time Felstorm deals damage, it increases the damage the target takes from you and your pets by 1% for 8 sec, up to 5%."
WordHunterWoW_ENDesc_Spell[387400] = "Chaos Bolt increases the damage of Chaos Bolt by 12% and reduces the cast time of Chaos Bolt by 10% for 5 sec.\n\nRain of Fire increases the damage of Rain of Fire by 12% for 5 sec.\n\nShadowburn increases the damage of Shadowburn by 12% for 5 sec."
WordHunterWoW_ENDesc_Spell[387432] = "Shadow Bolt increases the damage of your Demonbolt by 7%, stacking up to 4 times. Lasts 20 sec."
WordHunterWoW_ENDesc_Spell[387445] = "Summoning a Wild Imp has a 15% chance to summon a Imp Gang Boss instead. An Imp Gang Boss deals 50% additional damage. \n\nImplosions from Imp Gang Boss deal 50% increased damage."
WordHunterWoW_ENDesc_Spell[387475] = "Your Infernal's melee attacks cause its target to take 3% increased damage from its Immolation, stacking up to 15 times."
WordHunterWoW_ENDesc_Spell[387483] = "Doom deals 3% increased damage for each demon pet you have active."
WordHunterWoW_ENDesc_Spell[387494] = "Your Felguard deals 20% additional damage. Soul Strike now deals 25% of its damage to nearby enemies."
WordHunterWoW_ENDesc_Spell[387506] = "Your single target spells have a 35% chance to apply Havoc to a nearby enemy for 5.0 sec.\n\n Havoc\nMarks a target with Havoc for 5.0 sec, causing your single target spells to also strike the Havoc victim for 50% of the damage dealt."
WordHunterWoW_ENDesc_Spell[387509] = "Increases the base duration of Havoc by 3 sec.\n\nMayhem has an additional 10% chance to trigger."
WordHunterWoW_ENDesc_Spell[387522] = "When Chaos Bolt damages a target afflicted by Havoc, it explodes, dealing 190 damage to enemies within 8 yards."
WordHunterWoW_ENDesc_Spell[387526] = "Demons summoned from your Nether Portal deal 15% increased damage."
WordHunterWoW_ENDesc_Spell[387541] = "Hand of Gul'dan has a 15% chance to cast a second time on your target for free."
WordHunterWoW_ENDesc_Spell[387549] = "While your Felguard is active, your Wild Imps and Dreadstalkers deal 5% additional damage."
WordHunterWoW_ENDesc_Spell[387569] = "Each time your spells duplicate from Havoc, gain 1% increased damage for 6 sec. Stacks up to 5 times."
WordHunterWoW_ENDesc_Spell[387578] = "When Nether Portal ends, you summon a Pit Lord that blasts your target for 387 Fire damage every 0.9 sec for 10 sec."
WordHunterWoW_ENDesc_Spell[387600] = "When your Wild Imps expire or die, your other demons are inspired and gain 1% additional damage, stacking up to 10 times."
WordHunterWoW_ENDesc_Spell[387602] = "When your Wild Imps cast Fel Firebolt, you gain an application of Stolen Power. After you reach 75 applications, your next Demonbolt deals 60% increased damage or your next Shadow Bolt deals 60% increased damage."
WordHunterWoW_ENDesc_Spell[387617] = "Call upon the Covenants of the Shadowlands to aid you, restoring 2,280 health and increasing your Versatility by 10% for 12 sec.\n\nPassive: The Covenants have granted you a portion of their power, increasing your damage and healing by 4.0%."
WordHunterWoW_ENDesc_Spell[387625] = "When you Blackout Kick, your Stagger is reduced by 263, increased by up to 200% based on your missing health."
WordHunterWoW_ENDesc_Spell[387638] = "Blackout Kick's damage increased by 20% and it strikes an additional 2 targets."
WordHunterWoW_ENDesc_Spell[387761] = "Emerald Blossom and Verdant Embrace instantly heal you for 950 when cast."
WordHunterWoW_ENDesc_Spell[387765] = "Life Cocoon increases healing over time received by an additional 20%, and increases all periodic healing you deal by 20% for an additional 10 sec after the cocoon is removed."
WordHunterWoW_ENDesc_Spell[387781] = "Beacon of Light transfers an additional 5% of the amount healed."
WordHunterWoW_ENDesc_Spell[387786] = "Your Flash of Light heals for an additional 50% when cast on a target affected by your Beacon of Light."
WordHunterWoW_ENDesc_Spell[387787] = "Your Leech is increased by 2%."
WordHunterWoW_ENDesc_Spell[387791] = "Lay on Hands grants the target 30% increased armor for 8 sec and now ignores healing reduction effects."
WordHunterWoW_ENDesc_Spell[387801] = "Blessing of Freedom increases the target's movement speed by 30%. Blessing of Protection and Blessing of Sacrifice reduce the target's damage taken by 15%. These effects linger for 8 sec after the Blessing ends."
WordHunterWoW_ENDesc_Spell[387805] = "Holy Shock and Judgment have a 8% increased critical strike chance."
WordHunterWoW_ENDesc_Spell[387807] = "The cooldowns of your loss of control spells are reduced by 5 sec."
WordHunterWoW_ENDesc_Spell[387808] = "While empowered by Infusion of Light, Flash of Light heals for an additional 20% and Judgment refunds 0.5% of your maximum mana."
WordHunterWoW_ENDesc_Spell[387879] = "Increases Light of Dawn's healing by 5%."
WordHunterWoW_ENDesc_Spell[387893] = "After casting Holy Prism or Divine Toll you instantly cast Holy Shock every 5 sec. This effect lasts 15 sec."
WordHunterWoW_ENDesc_Spell[387972] = "Reduces the cooldown of Amplify Curse by 15 sec."
WordHunterWoW_ENDesc_Spell[387976] = "Rips a hole in time and space, opening a random portal that damages your target:\n\nShadowy Tear\nDeals 3,143 Shadow damage over 14 sec.\n\nUnstable Tear\nDeals 2,696 Chaos damage over 6 sec.\n\nChaos Tear\nFires a Chaos Bolt, dealing 1,240 Chaos damage. This Chaos Bolt always critically strikes and your critical strike chance increases its damage.\n\nGenerates 3 Soul Shard Fragments."
WordHunterWoW_ENDesc_Spell[387991] = "Your Invigorating Mist healing is increased by 20% and your Enveloping Mist also heals allies with Renewing Mist for 8% of its healing.\n\nThe duration of Enveloping Mist is increased by 4 sec while you have a celestial summoned."
WordHunterWoW_ENDesc_Spell[388004] = "Raging Blow causes every strike of your next Rampage to deal an additional 20% damage, stacking up to 5 times."
WordHunterWoW_ENDesc_Spell[388007] = "Bless an ally for 30 sec, causing 12% of all healing to be converted into damage onto a nearby enemy and 12% of all damage to be converted into healing onto an injured ally within 40 yds.\n\nBlessing of the Seasons: Turns to Autumn after use."
WordHunterWoW_ENDesc_Spell[388018] = "Light of Dawn increases your next Light of the Martyr by 10% for each ally healed, and allows that Light of the Martyr to heal through Beacon of Light.\n\nLight of the Martyr damages you over 5 sec instead of instantly."
WordHunterWoW_ENDesc_Spell[388020] = "Gust of Mists has a 30% chance to do 100% more healing."
WordHunterWoW_ENDesc_Spell[388023] = "Your Tiger Palm, Blackout Kick, Rising Sun Kick, and Crackling Jade Lightning heal up to 5 injured allies within 40 yds for 25% of the damage done, split evenly among them."
WordHunterWoW_ENDesc_Spell[388031] = "Chi Cocoons now apply Enveloping Mist for 4 sec when they expire or are consumed, and Chi-Ji's Gusts of Mists healing is increased by 20% and Yu'lon's Soothing Breath healing is increased by 500%."
WordHunterWoW_ENDesc_Spell[388035] = "Damage taken reduced by 3%."
WordHunterWoW_ENDesc_Spell[388038] = "While channeling Mana Tea you exhale the breath of Yu'lon, healing up to 5 allies within 15 yards for 337 every 0.4 sec."
WordHunterWoW_ENDesc_Spell[388039] = "The duration of Survival of the Fittest is increased by 2.0 sec."
WordHunterWoW_ENDesc_Spell[388042] = "Survival of the Fittest reduces damage taken by an additional 20%."
WordHunterWoW_ENDesc_Spell[388045] = "Call forth a Sentinel Owl to the target location within 40 yds, granting you unhindered vision. Your attacks ignore line of sight against any target in this area.\n\nEvery 150 Focus spent grants you 1 sec of the Sentinel Owl when cast, up to a maximum of 12 sec. The Sentinel Owl can only be summoned when it will last at least 5 sec."
WordHunterWoW_ENDesc_Spell[388049] = "Raging Blow gains an extra charge."
WordHunterWoW_ENDesc_Spell[388056] = "Sentinel Owl now also grants unhindered vision to party members while active."
WordHunterWoW_ENDesc_Spell[388057] = "While the Sentinel Owl is active, your party gains 3% leech."
WordHunterWoW_ENDesc_Spell[388106] = "Throw Glaive causes targets to take an additional 80% of damage dealt as Chaos over 6 sec."
WordHunterWoW_ENDesc_Spell[388107] = "Each time Immolation Aura deals damage, 35% of the damage dealt by up to 3 critical strikes is gathered as Ragefire.\n\nWhen Immolation Aura expires you explode, dealing all stored Ragefire damage to nearby enemies."
WordHunterWoW_ENDesc_Spell[388108] = "Damaging an enemy before they damage you increases your critical strike chance by 10% for 5 sec.\n\nVengeful Retreat refreshes your potential to trigger this effect on any enemies you are in combat with."
WordHunterWoW_ENDesc_Spell[388110] = "You deal 20% increased damage to enemies for 5 sec after Sigil of Misery's effect on them ends."
WordHunterWoW_ENDesc_Spell[388112] = "When you activate Metamorphosis, the cooldowns of Blade Dance and Eye Beam are immediately reset."
WordHunterWoW_ENDesc_Spell[388113] = "Chaos Nova, Eye Beam, and Immolation Aura gain bonuses when striking 1 target.\n\n Chaos Nova:\nStun duration increased by 2 sec.\n\n Eye Beam:\nDeals 30% increased damage.\n\n Immolation Aura:\nAlways critically strikes."
