WordHunterWoW_ENDesc_Spell[396286] = "Gather earthen power beneath your enemy's feet and send them hurtling upwards, dealing 1,602 Volcanic damage to the target and nearby enemies.\n\nEmpowering expands the area of effect.\n\nI:   3 yd radius.\n\nII:  6 yd radius.\n\nIII: 9 yd radius."
WordHunterWoW_ENDesc_Spell[396309] = "Unlock the appearances of the Lionguard Ensemble upon completion of the Heritage storyline."
WordHunterWoW_ENDesc_Spell[396571] = "Your dragon scales increase your armor by 75%."
